return [ 'project-id-version' => 'fluid-checkout','mime-version' => '1.0','content-type' => 'text/plain; charset=utf-8','content-transfer-encoding' => '8bit','language-team' => 'Fluid Checkout','last-translator' => 'Fluid Checkout','pot-creation-date' => '2025-03-05 23:46+0000','report-msgid-bugs-to' => 'https://fluidcheckout.com/support','x-poedit-basepath' => '..','x-poedit-keywordslist' => '__;_e;_ex:1,2c;_n:1,2;_n_noop:1,2;_nx:1,2,4c;_nx_noop:1,2,3c;_x:1,2c;esc_attr__;esc_attr_e;esc_attr_x:1,2c;esc_html__;esc_html_e;esc_html_x:1,2c','x-poedit-searchpath-0' => '.','x-poedit-searchpathexcluded-0' => '*.js','x-poedit-sourcecharset' => 'UTF-8','plural-forms' => 'nplurals=2; plural=(n != 1);','messages' => ['WooCommerce' => 'વૂકોમર્સ','Go to Plugin Search' => 'પ્લગઇન શોધ પર જાઓ','Activate %s' => '%s સક્રિય કરો','<strong>%1$s</strong> requires <strong>%2$s</strong> to be installed and activated. <a href="%4$s">%3$s</a>' => '<strong>%1$s ને</strong> <strong>%2$s</strong> ઇન્સ્ટોલ અને સક્રિય કરવાની જરૂર છે. <a href="%4$s">%3$s</a>','Enter your code here' => 'તમારો કોડ અહીં દાખલ કરો','Add %s' => '%s ઉમેરો','Remove' => 'દૂર કરો','Order number and receipt will be sent to this email address.' => 'ઓર્ડર નંબર અને રસીદ આ ઇમેઇલ સરનામાં પર મોકલવામાં આવશે.','Apartment, unit, building, floor, etc.' => 'એપાર્ટમેન્ટ, યુનિટ, મકાન, માળ, વગેરે.','Shipping phone' => 'શિપિંગ ફોન','Only used for shipping-related questions.' => 'ફક્ત શિપિંગ સંબંધિત પ્રશ્નો માટે જ વપરાય છે.','Single step' => 'એક પગલું','Click to go to the order summary' => 'ઓર્ડર સારાંશ પર જવા માટે ક્લિક કરો','Cart total:' => 'કાર્ટ કુલ:','Proceed to %s' => '%s પર આગળ વધો','Proceed to contact' => 'સંપર્ક કરવા આગળ વધો','Proceed to shipping' => 'શિપિંગ માટે આગળ વધો','Proceed to billing' => 'બિલિંગ પર આગળ વધો','Proceed to payment' => 'ચુકવણી માટે આગળ વધો','Shipping method' => 'શિપિંગ પદ્ધતિ','Additional notes' => 'વધારાની નોંધો','Payment method' => 'ચુકવણી પદ્ધતિ','Step %1$s of %2$s' => '%2$s માંથી %1$s પગલું','Change: %s' => 'ફેરફાર: %s','Not selected yet.' => 'હજુ સુધી પસંદ થયેલ નથી.','Same as shipping address' => 'શિપિંગ સરનામા જેવું જ','Same as billing address' => 'બિલિંગ સરનામાં જેવું જ','Order summary' => 'ઓર્ડર સારાંશ','Edit cart' => 'કાર્ટમાં ફેરફાર કરો','Did you mean %s?' => 'શું તમારો મતલબ %s હતો?','Change email address to: {suggestion-value}' => 'ઇમેઇલ સરનામું આના પર બદલો: {suggestion-value}','This is a required field.' => 'આ એક આવશ્યક ક્ષેત્ર છે.','This is not a valid email address.' => 'આ માન્ય ઇમેઇલ સરનામું નથી.','This field does not match the related field value.' => 'આ ફીલ્ડ સંબંધિત ફીલ્ડ મૂલ્ય સાથે મેળ ખાતું નથી.','The CPF number "{cpf_number}" is invalid.' => 'CPF નંબર &quot;{cpf_number}&quot; અમાન્ય છે.','The CNPJ number "{cnpj_number}" is invalid.' => 'CNPJ નંબર &quot;{cnpj_number}&quot; અમાન્ય છે.','(Required)' => '(જરૂરી)','Checkout Header - Desktop' => 'ચેકઆઉટ હેડર - ડેસ્કટોપ','Display widgets on the checkout header for large screens. Only displayed if using the plugin\'s checkout header.' => 'મોટી સ્ક્રીન માટે ચેકઆઉટ હેડર પર વિજેટ્સ પ્રદર્શિત કરો. પ્લગઇનના ચેકઆઉટ હેડરનો ઉપયોગ કરવામાં આવે તો જ પ્રદર્શિત થાય છે.','Checkout Header - Mobile' => 'ચેકઆઉટ હેડર - મોબાઇલ','Display widgets below the checkout header for mobile devices. Only displayed if using the plugin\'s checkout header.' => 'મોબાઇલ ઉપકરણો માટે ચેકઆઉટ હેડરની નીચે વિજેટ્સ પ્રદર્શિત કરો. પ્લગઇનના ચેકઆઉટ હેડરનો ઉપયોગ કરવામાં આવે તો જ પ્રદર્શિત થાય છે.','Checkout Sidebar' => 'ચેકઆઉટ સાઇડબાર','Display widgets on the checkout sidebar after the order summary.' => 'ઓર્ડર સારાંશ પછી ચેકઆઉટ સાઇડબાર પર વિજેટ્સ દર્શાવો.','Checkout Order Summary' => 'ચેકઆઉટ ઓર્ડર સારાંશ','Display widgets inside the order summary at the checkout page.' => 'ચેકઆઉટ પેજ પર ઓર્ડર સારાંશની અંદર વિજેટ્સ દર્શાવો.','Checkout Below Place Order' => 'નીચે ચેકઆઉટ કરો ઓર્ડર આપો','Display widgets below the place order button at the checkout page.' => 'ચેકઆઉટ પેજ પર ઓર્ડર આપો બટનની નીચે વિજેટ્સ પ્રદર્શિત કરો.','Checkout Footer' => 'ચેકઆઉટ ફૂટર','Display widgets on the checkout footer. Only displayed if using the plugin\'s checkout footer.' => 'ચેકઆઉટ ફૂટર પર વિજેટ્સ પ્રદર્શિત કરો. પ્લગઇનના ચેકઆઉટ ફૂટરનો ઉપયોગ કરીને જ પ્રદર્શિત થાય છે.','Classic' => 'ક્લાસિક','Boxed' => 'બોક્સવાળું','Split' => 'વિભાજન','Minimalist' => 'મિનિમલિસ્ટ','Fluid Checkout and Delivery Date plugins by CodeRockz' => 'કોડરોક્ઝ દ્વારા ફ્લુઇડ ચેકઆઉટ અને ડિલિવરી તારીખ પ્લગઇન્સ','<p>We detected that you are using the plugins Delivery & Pickup Date Time for WooCommerce (free and PRO) by CodeRockz. Integration with these plugins have been moved to Fluid Checkout PRO.</p>' => '<p>અમને જાણવા મળ્યું છે કે તમે CodeRockz દ્વારા WooCommerce (મફત અને PRO) માટે ડિલિવરી અને પિકઅપ તારીખ સમય પ્લગઇન્સનો ઉપયોગ કરી રહ્યા છો. આ પ્લગઇન્સ સાથેનું એકીકરણ Fluid Checkout PRO માં ખસેડવામાં આવ્યું છે.</p>','Upgrade to PRO' => 'PRO પર અપગ્રેડ કરો','Fluid Checkout database updated successfully' => 'ફ્લુઇડ ચેકઆઉટ ડેટાબેઝ સફળતાપૂર્વક અપડેટ થયો','The database changes where applied successfully.' => 'જ્યાં સફળતાપૂર્વક લાગુ કરવામાં આવે છે ત્યાં ડેટાબેઝ બદલાય છે.','Dismiss' => 'કાઢી નાખો','Fluid Checkout database update' => 'ફ્લુઇડ ચેકઆઉટ ડેટાબેઝ અપડેટ','Some changes to the database are required. As with any update, we recommend you to <strong>take a full backup of your website before proceeding</strong>.' => 'ડેટાબેઝમાં કેટલાક ફેરફારો જરૂરી છે. કોઈપણ અપડેટની જેમ, અમે ભલામણ કરીએ છીએ કે તમે <strong>આગળ વધતા પહેલા તમારી વેબસાઇટનો સંપૂર્ણ બેકઅપ લો</strong> .','Update database' => 'ડેટાબેઝ અપડેટ કરો','Fluid Checkout is not compatible with the Divi Builder checkout layout' => 'ફ્લુઇડ ચેકઆઉટ, Divi બિલ્ડર ચેકઆઉટ લેઆઉટ સાથે સુસંગત નથી.','<p>Fluid Checkout needs the classic WooCommerce shortcode-based checkout form to work. When using the Divi Builder to customize the look and feel of the checkout page, the classic shortcodes are replaced with custom widgets from the Divi Builder for each part of the checkout page. These custom widgets are not compatible with Fluid Checkout.</p><p>Please edit your checkout page replacing the Divi Builder widgets with the a text widget containing the shortcode <code>[woocommerce_checkout]</code>.</p>' => '<p>ફ્લુઇડ ચેકઆઉટને કામ કરવા માટે ક્લાસિક WooCommerce શોર્ટકોડ-આધારિત ચેકઆઉટ ફોર્મની જરૂર છે. ચેકઆઉટ પેજના દેખાવ અને અનુભૂતિને કસ્ટમાઇઝ કરવા માટે Divi બિલ્ડરનો ઉપયોગ કરતી વખતે, ચેકઆઉટ પેજના દરેક ભાગ માટે ક્લાસિક શોર્ટકોડ્સને Divi બિલ્ડરના કસ્ટમ વિજેટ્સથી બદલવામાં આવે છે. આ કસ્ટમ વિજેટ્સ ફ્લુઇડ ચેકઆઉટ સાથે સુસંગત નથી.</p><p> કૃપા કરીને તમારા ચેકઆઉટ પેજને Divi બિલ્ડર વિજેટ્સને શોર્ટકોડ <code>[woocommerce_checkout]</code> ધરાવતા ટેક્સ્ટ વિજેટથી બદલીને સંપાદિત કરો.</p>','Edit the checkout page' => 'ચેકઆઉટ પેજમાં ફેરફાર કરો','Read the documentation.' => 'દસ્તાવેજીકરણ વાંચો.','Germanized PRO multistep checkout feature needs to be disabled when using Fluid Checkout' => 'ફ્લુઇડ ચેકઆઉટનો ઉપયોગ કરતી વખતે જર્મનાઇઝ્ડ PRO મલ્ટિસ્ટેપ ચેકઆઉટ સુવિધાને અક્ષમ કરવાની જરૂર છે.','When using Fluid Checkout, the multistep feature from the Germanized PRO plugin becomes unnecessary and can cause <strong>critical errors while processing new orders</strong>. Please disable the Germanized PRO multistep checkout feature in the plugin settings.' => 'ફ્લુઇડ ચેકઆઉટનો ઉપયોગ કરતી વખતે, જર્મનાઇઝ્ડ પ્રો પ્લગઇનમાંથી મલ્ટિસ્ટેપ સુવિધા બિનજરૂરી બની જાય છે અને <strong>નવા ઓર્ડરની પ્રક્રિયા કરતી વખતે ગંભીર ભૂલો</strong> પેદા કરી શકે છે. કૃપા કરીને પ્લગઇન સેટિંગ્સમાં જર્મનાઇઝ્ડ પ્રો મલ્ટિસ્ટેપ ચેકઆઉટ સુવિધાને અક્ષમ કરો.','Go to Germanized settings' => 'જર્મનીકૃત સેટિંગ્સ પર જાઓ','Thanks for choosing Fluid Checkout!' => 'ફ્લુઇડ ચેકઆઉટ પસંદ કરવા બદલ આભાર!','You have been using the plugin for a while now. How do you like it so far? <br>Please give us a quick rating, we appreciate every bit of feedback and it encourages us to keep improving the plugin :)' => 'તમે ઘણા સમયથી પ્લગઇનનો ઉપયોગ કરી રહ્યા છો. તમને અત્યાર સુધી તે કેવું લાગ્યું?<br> કૃપા કરીને અમને ઝડપી રેટિંગ આપો, અમે દરેક પ્રતિસાદની પ્રશંસા કરીએ છીએ અને તે અમને પ્લગઇનને સુધારવાનું ચાલુ રાખવા માટે પ્રોત્સાહિત કરે છે :)','Rate the plugin' => 'પ્લગઇનને રેટ કરો','I need help!' => 'મને મદદની જરૂર છે!','Some features of WooCommerce Checkout Manager by Quadlayers might not work as expected when using it with Fluid Checkout. Read <a href="%s">our documentation</a> for more information and alternative solutions.' => 'ફ્લુઇડ ચેકઆઉટ સાથે ઉપયોગ કરતી વખતે ક્વાડલેયર્સ દ્વારા WooCommerce ચેકઆઉટ મેનેજરની કેટલીક સુવિધાઓ અપેક્ષા મુજબ કામ ન પણ કરે. વધુ માહિતી અને વૈકલ્પિક ઉકેલો માટે <a href="%s">અમારા દસ્તાવેજો</a> વાંચો.','Read documentation' => 'દસ્તાવેજીકરણ વાંચો','Don\'t show this again' => 'આ ફરી બતાવશો નહીં','Fluid Checkout PRO' => 'ફ્લુઇડ ચેકઆઉટ પ્રો','More design templates' => 'વધુ ડિઝાઇન નમૂનાઓ','Optimized cart page' => 'ઑપ્ટિમાઇઝ કરેલ કાર્ટ પેજ','Optimized order received / thank you page' => 'ઑપ્ટિમાઇઝ કરેલ ઓર્ડર પ્રાપ્ત થયો / આભાર પૃષ્ઠ','Edit cart contents at checkout page' => 'ચેકઆઉટ પેજ પર કાર્ટ સામગ્રી સંપાદિત કરો','Account matching / user matching' => 'એકાઉન્ટ મેચિંગ / વપરાશકર્તા મેચિંગ','Trust symbols on the cart and thank you pages' => 'કાર્ટ અને આભાર પૃષ્ઠો પર ટ્રસ્ટ પ્રતીકો','More positions for the coupon code on the checkout page' => 'ચેકઆઉટ પેજ પર કૂપન કોડ માટે વધુ સ્થાનો','International phone numbers' => 'આંતરરાષ્ટ્રીય ફોન નંબરો','Gift messages and packing slips' => 'ભેટ સંદેશાઓ અને પેકિંગ સ્લિપ','Local pickup and in-store collection' => 'સ્થાનિક પિકઅપ અને સ્ટોરમાં સંગ્રહ','EU-VAT Assistant' => 'EU-VAT સહાયક','I already have it – Hide this offer' => 'મારી પાસે પહેલેથી જ છે - આ ઓફર છુપાવો','Activated' => 'સક્રિય કરેલ','Address book' => 'સરનામાં પુસ્તિકા','Select an image' => 'એક છબી પસંદ કરો','Cart layout' => 'કાર્ટ લેઆઉટ','Cart optimizations' => 'કાર્ટ ઑપ્ટિમાઇઝેશન','Enable cart page optimizations' => 'કાર્ટ પેજ ઑપ્ટિમાઇઝેશન સક્ષમ કરો','Header and footer template' => 'હેડર અને ફૂટર ટેમ્પલેટ','Controls whether to use the distraction free page header and footer or keep the currently active theme\'s header and footer.' => 'વિક્ષેપ મુક્ત પેજ હેડર અને ફૂટરનો ઉપયોગ કરવો કે હાલમાં સક્રિય થીમના હેડર અને ફૂટરને રાખવું તે નિયંત્રિત કરે છે.','Distraction free header and footer' => 'વિક્ષેપ મુક્ત હેડર અને ફૂટર','Theme\'s header and footer' => 'થીમનું હેડર અને ફૂટર','Cart elements' => 'કાર્ટ તત્વો','Make the order summary stay visible on the cart page while scrolling' => 'સ્ક્રોલ કરતી વખતે કાર્ટ પેજ પર ઓર્ડર સારાંશ દૃશ્યમાન રહે તેવો બનાવો.','Coupon codes' => 'કૂપન કોડ્સ','Hidden' => 'છુપાયેલ','Before the cart items section' => 'કાર્ટ આઇટમ વિભાગ પહેલાં','Inside the cart items section' => 'કાર્ટ આઇટમ વિભાગની અંદર','After the cart items section' => 'કાર્ટ આઇટમ્સ વિભાગ પછી','Before the shipping section' => 'શિપિંગ વિભાગ પહેલાં','After the shipping section' => 'શિપિંગ વિભાગ પછી','Before the order summary' => 'ઓર્ડર સારાંશ પહેલાં','Inside the order summary' => 'ઓર્ડર સારાંશની અંદર','Before the order totals' => 'ઓર્ડરના કુલ જથ્થા પહેલાં','After the order totals' => 'ઓર્ડરના કુલ જથ્થા પછી','After the order summary' => 'ઓર્ડર સારાંશ પછી','Shipping' => 'શિપિંગ','Select position where to display the shipping costs and calculator on the cart page.' => 'કાર્ટ પેજ પર શિપિંગ ખર્ચ અને કેલ્ક્યુલેટર ક્યાં પ્રદર્શિત કરવા તે સ્થાન પસંદ કરો.','Display as a cart section' => 'કાર્ટ વિભાગ તરીકે દર્શાવો','Cross-sells' => 'ક્રોસ-સેલ્સ','Select position where to display the cross-sells section on the cart page.' => 'કાર્ટ પેજ પર ક્રોસ-સેલ્સ વિભાગ ક્યાં પ્રદર્શિત કરવો તે સ્થાન પસંદ કરો.','Before the cart actions' => 'કાર્ટ ક્રિયાઓ પહેલાં','After the cart actions' => 'કાર્ટ ક્રિયાઓ પછી','Layout of cross-sell items on the cart page.' => 'કાર્ટ પેજ પર ક્રોસ-સેલ વસ્તુઓનો લેઆઉટ.','Optimized horizontal cross-sells layout' => 'ઑપ્ટિમાઇઝ કરેલ આડું ક્રોસ-સેલ્સ લેઆઉટ','Theme\'s cross-sells layout' => 'થીમનું ક્રોસ-સેલ્સ લેઆઉટ','Number of cross-sell items to display on the cart page' => 'કાર્ટ પેજ પર પ્રદર્શિત કરવા માટે ક્રોસ-સેલ વસ્તુઓની સંખ્યા','Add widget areas to the cart page' => 'કાર્ટ પેજ પર વિજેટ વિસ્તારો ઉમેરો','These widget areas are used to add trust symbols and trust badges on the cart page.' => 'આ વિજેટ વિસ્તારોનો ઉપયોગ કાર્ટ પેજ પર ટ્રસ્ટ સિમ્બોલ અને ટ્રસ્ટ બેજ ઉમેરવા માટે થાય છે.','Checkout' => 'ચેકઆઉટ','Checkout layout' => 'ચેકઆઉટ લેઆઉટ','Design template' => 'ડિઝાઇન ટેમ્પલેટ','Dark mode' => 'ડાર્ક મોડ','Enable dark mode' => 'ડાર્ક મોડ ચાલુ કરો','Logo image' => 'લોગોની છબી','Choose an image to be displayed on the checkout page header. Only applies when using the distraction free header and footer.' => 'ચેકઆઉટ પેજ હેડર પર પ્રદર્શિત કરવા માટે એક છબી પસંદ કરો. વિક્ષેપ મુક્ત હેડર અને ફૂટરનો ઉપયોગ કરતી વખતે જ લાગુ પડે છે.','Header background color' => 'હેડર પૃષ્ઠભૂમિ રંગ','Choose a background color for the checkout page header. Only applies when using the distraction free header and footer.' => 'ચેકઆઉટ પેજ હેડર માટે બેકગ્રાઉન્ડ રંગ પસંદ કરો. ફક્ત વિક્ષેપ મુક્ત હેડર અને ફૂટરનો ઉપયોગ કરતી વખતે જ લાગુ પડે છે.','HTML color value. ie: #f3f3f3' => 'HTML રંગ મૂલ્ય. એટલે કે: #f3f3f3','Page background color' => 'પૃષ્ઠ પૃષ્ઠભૂમિ રંગ','Choose a background color for the checkout page. Color is applied to the <em>body</em> element.' => 'ચેકઆઉટ પેજ માટે બેકગ્રાઉન્ડ રંગ પસંદ કરો. રંગ <em>બોડી</em> એલિમેન્ટ પર લાગુ થાય છે.','Footer background color' => 'ફૂટર પૃષ્ઠભૂમિ રંગ','Choose a background color for the checkout page footer. Only applies when using the distraction free header and footer.' => 'ચેકઆઉટ પેજ ફૂટર માટે બેકગ્રાઉન્ડ રંગ પસંદ કરો. ફક્ત વિક્ષેપ મુક્ત હેડર અને ફૂટરનો ઉપયોગ કરતી વખતે જ લાગુ પડે છે.','Progress bar' => 'પ્રગતિ પટ્ટી','Display the checkout progress bar when using multi-step checkout layout' => 'મલ્ટી-સ્ટેપ ચેકઆઉટ લેઆઉટનો ઉપયોગ કરતી વખતે ચેકઆઉટ પ્રોગ્રેસ બાર દર્શાવો','Make the checkout progress bar stay visible while scrolling' => 'સ્ક્રોલ કરતી વખતે ચેકઆઉટ પ્રોગ્રેસ બારને દૃશ્યમાન રાખો','Express checkout' => 'એક્સપ્રેસ ચેકઆઉટ','Enable the express checkout section' => 'એક્સપ્રેસ ચેકઆઉટ વિભાગ સક્ષમ કરો','Displays the express checkout section at checkout when supported payment gateways have this feature enabled.' => 'જ્યારે સપોર્ટેડ પેમેન્ટ ગેટવેમાં આ સુવિધા સક્ષમ હોય ત્યારે ચેકઆઉટ વખતે એક્સપ્રેસ ચેકઆઉટ વિભાગ દર્શાવે છે.','Display express checkout buttons in one line for larger screens' => 'મોટી સ્ક્રીન માટે એક્સપ્રેસ ચેકઆઉટ બટનોને એક જ લાઇનમાં દર્શાવો','Ignore additional checkout required fields when paying with a compatible express checkout payment gateway' => 'સુસંગત એક્સપ્રેસ ચેકઆઉટ પેમેન્ટ ગેટવે વડે ચુકવણી કરતી વખતે વધારાના ચેકઆઉટ જરૂરી ફીલ્ડ્સને અવગણો.','Make the order summary stay visible while scrolling' => 'સ્ક્રોલ કરતી વખતે ઓર્ડર સારાંશ દૃશ્યમાન રાખો','Choose a background color for the order summary section.' => 'ઓર્ડર સારાંશ વિભાગ માટે પૃષ્ઠભૂમિ રંગ પસંદ કરો.','Highlight the order totals row in the order summary table' => 'ઓર્ડર સારાંશ કોષ્ટકમાં ઓર્ડર કુલ પંક્તિને હાઇલાઇટ કરો.','Most useful when the order summary section does not have a highlighted background color. Might also apply to the Cart, Order Received and View Order pages when using Fluid Checkout PRO.' => 'જ્યારે ઓર્ડર સારાંશ વિભાગમાં હાઇલાઇટ કરેલ પૃષ્ઠભૂમિ રંગ ન હોય ત્યારે સૌથી વધુ ઉપયોગી. ફ્લુઇડ ચેકઆઉટ પ્રોનો ઉપયોગ કરતી વખતે કાર્ટ, ઓર્ડર પ્રાપ્ત અને ઓર્ડર જુઓ પૃષ્ઠો પર પણ લાગુ પડી શકે છે.','Action link on the order summary at checkout.' => 'ચેકઆઉટ વખતે ઓર્ડર સારાંશ પર ક્રિયા લિંક.','Edit cart link' => 'કાર્ટ લિંક સંપાદિત કરો','Cart items count' => 'કાર્ટમાં વસ્તુઓની સંખ્યા','Link to shop page' => 'દુકાનના પેજની લિંક','Cart items' => 'કાર્ટ વસ્તુઓ','Hide cart items errors at the checkout page' => 'ચેકઆઉટ પેજ પર કાર્ટ આઇટમની ભૂલો છુપાવો','Do not display the cart items errors message at the top of the checkout page. When submitting the checkout form to complete the purchase, these error messages will always be displayed.' => 'ચેકઆઉટ પેજની ટોચ પર કાર્ટ આઇટમ્સ ભૂલ સંદેશ પ્રદર્શિત કરશો નહીં. ખરીદી પૂર્ણ કરવા માટે ચેકઆઉટ ફોર્મ સબમિટ કરતી વખતે, આ ભૂલ સંદેશાઓ હંમેશા પ્રદર્શિત થશે.','Place order' => 'ઓર્ડર આપો','Define the position to display "Place order" and terms checkbox section.' => '&quot;પ્લેસ ઓર્ડર&quot; અને ટર્મ્સ ચેકબોક્સ વિભાગ પ્રદર્શિત કરવા માટેની સ્થિતિ વ્યાખ્યાયિત કરો.','Some options might not be compatible with some plugins and themes.' => 'કેટલાક વિકલ્પો કેટલાક પ્લગઈન્સ અને થીમ્સ સાથે સુસંગત ન પણ હોય શકે.','Below the payment section' => 'ચુકવણી વિભાગ નીચે','Below the order summary' => 'ઓર્ડર સારાંશ નીચે','Both below the payment section and the order summary' => 'ચુકવણી વિભાગની નીચે અને ઓર્ડર સારાંશ બંને','Add widget areas to the checkout page' => 'ચેકઆઉટ પેજ પર વિજેટ વિસ્તારો ઉમેરો','These widget areas are used to add trust symbols and trust badges on the checkout page.' => 'આ વિજેટ વિસ્તારોનો ઉપયોગ ચેકઆઉટ પેજ પર ટ્રસ્ટ સિમ્બોલ અને ટ્રસ્ટ બેજ ઉમેરવા માટે થાય છે.','Display the coupon codes section title' => 'કૂપન કોડ્સ વિભાગ શીર્ષક દર્શાવો','Select position where to display the coupon codes section on the checkout page.' => 'ચેકઆઉટ પેજ પર કૂપન કોડ વિભાગ ક્યાં પ્રદર્શિત કરવો તે સ્થાન પસંદ કરો.','Before the checkout steps' => 'ચેકઆઉટ પગલાં પહેલાં','As a substep before payment methods' => 'ચુકવણી પદ્ધતિઓ પહેલાંના સબસ્ટેપ તરીકે','As a substep after payment methods' => 'ચુકવણી પદ્ધતિઓ પછીના પગલા તરીકે','Default button style' => 'ડિફોલ્ટ બટન શૈલી','"Add" link button' => '&quot;લિંક ઉમેરો&quot; બટન','Checkout fields' => 'ચેકઆઉટ ફીલ્ડ્સ','Optional fields' => 'વૈકલ્પિક ક્ષેત્રો','Hide optional fields behind a link button' => 'લિંક બટન પાછળ વૈકલ્પિક ફીલ્ડ છુપાવો','It is recommended to keep this option checked to reduce the number of open input fields, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#1-address-line-2--company-name-can-safely-be-collapsed-behind-a-link" target="_blank">read the research</a>.' => 'ખુલ્લા ઇનપુટ ફીલ્ડ્સની સંખ્યા ઘટાડવા માટે આ વિકલ્પને ચેક કરીને રાખવાની ભલામણ કરવામાં આવે છે, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#1-address-line-2--company-name-can-safely-be-collapsed-behind-a-link" target="_blank">સંશોધન વાંચો</a> .','Do not hide "Address line 2" fields behind a link button' => 'લિંક બટન પાછળ &quot;એડ્રેસ લાઇન 2&quot; ફીલ્ડ છુપાવશો નહીં.','Recommended only when most customers actually need the "Address line 2" field, or when getting the right shipping address is crucial (ie. if delivering food and other perishable products).' => 'જ્યારે મોટાભાગના ગ્રાહકોને ખરેખર &quot;એડ્રેસ લાઇન 2&quot; ફીલ્ડની જરૂર હોય, અથવા જ્યારે યોગ્ય શિપિંગ સરનામું મેળવવું મહત્વપૂર્ણ હોય (દા.ત. ખોરાક અને અન્ય નાશવંત ઉત્પાદનો પહોંચાડતી વખતે) ત્યારે જ ભલામણ કરવામાં આવે છે.','Billing address' => 'બિલિંગ સરનામું','Select position where to display the billing address section on the checkout page.' => 'ચેકઆઉટ પેજ પર બિલિંગ સરનામું વિભાગ ક્યાં પ્રદર્શિત કરવો તે સ્થાન પસંદ કરો.','As a step before shipping' => 'શિપિંગ પહેલાંના પગલા તરીકે','As a sub-step before the shipping address section' => 'શિપિંગ સરનામું વિભાગ પહેલાં પેટા-પગલાં તરીકે','As a sub-step after the shipping address section' => 'શિપિંગ સરનામું વિભાગ પછી પેટા-પગલાં તરીકે','As a step after shipping' => 'શિપિંગ પછીના પગલા તરીકે','As a sub-step before the payment section' => 'ચુકવણી વિભાગ પહેલાંના પેટા-પગલાં તરીકે','Force billing and shipping addresses to the same (single section)' => 'બિલિંગ અને શિપિંગ સરનામાં સમાન (એક વિભાગ) પર ફરજિયાત કરો','Checkbox for "Same as shipping/billing address" checked by default' => '&quot;શિપિંગ/બિલિંગ સરનામાં જેવું જ&quot; માટે ચેકબોક્સ ડિફૉલ્ટ રૂપે ચેક કરેલ છે','The checkbox "Same as shiping address" will start as checked by default when the shipping address section is displayed first. <br>The checkbox "Same as billing address" will start as checked by default when the billing address section is displayed first. <br> It is recommended to leave this option checked as to significantly reduce the number of open input fields at checkout, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#3-default-billing--shipping-and-hide-the-fields-entirely" target="_blank">read the research</a>.' => 'જ્યારે શિપિંગ સરનામું વિભાગ પહેલા પ્રદર્શિત થશે ત્યારે &quot;શિપિંગ સરનામાં જેવું જ&quot; ચેકબોક્સ ડિફોલ્ટ રૂપે ચેક કરેલ તરીકે શરૂ થશે.<br> જ્યારે બિલિંગ સરનામું વિભાગ પહેલા પ્રદર્શિત થશે ત્યારે &quot;બિલિંગ સરનામાં જેવું જ&quot; ચેકબોક્સ ડિફોલ્ટ રૂપે ચેક કરેલ તરીકે શરૂ થશે.<br> ચેકઆઉટ વખતે ખુલ્લા ઇનપુટ ફીલ્ડ્સની સંખ્યામાં નોંધપાત્ર ઘટાડો કરવા માટે આ વિકલ્પને ચેક કરેલ રાખવાની ભલામણ કરવામાં આવે છે, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#3-default-billing--shipping-and-hide-the-fields-entirely" target="_blank">સંશોધન વાંચો</a> .','Highlight the billing address section in the checkout form' => 'ચેકઆઉટ ફોર્મમાં બિલિંગ સરનામાં વિભાગને હાઇલાઇટ કરો.','Shipping address' => 'શિપિંગ સરનામું','Highlight the shipping address section in the checkout form' => 'ચેકઆઉટ ફોર્મમાં શિપિંગ સરનામું વિભાગ હાઇલાઇટ કરો.','Shipping methods' => 'શિપિંગ પદ્ધતિઓ','Choose in which position to display the shipping methods section.' => 'શિપિંગ પદ્ધતિઓ વિભાગ કઈ સ્થિતિમાં પ્રદર્શિત કરવો તે પસંદ કરો.','Before shipping address' => 'શિપિંગ સરનામું પહેલાં','After shipping address' => 'શિપિંગ સરનામું પછી','Local pickup' => 'સ્થાનિક પિકઅપ','Removes shipping address section when a local pickup shipping method is selected.' => 'જ્યારે સ્થાનિક પિકઅપ શિપિંગ પદ્ધતિ પસંદ કરવામાં આવે ત્યારે શિપિંગ સરનામું વિભાગ દૂર કરે છે.','Replaces the shipping address with the pickup point location when a local pickup shipping method is selected.' => 'જ્યારે સ્થાનિક પિકઅપ શિપિંગ પદ્ધતિ પસંદ કરવામાં આવે ત્યારે શિપિંગ સરનામાંને પિકઅપ પોઈન્ટ સ્થાન સાથે બદલે છે.','Choose which address to save as the shipping address for local pickup orders.' => 'સ્થાનિક પિકઅપ ઓર્ડર માટે શિપિંગ સરનામું તરીકે કયું સરનામું સાચવવું તે પસંદ કરો.','Save the selected pickup location' => 'પસંદ કરેલ પિકઅપ સ્થાન સાચવો','Save same as the billing address' => 'બિલિંગ સરનામાંની જેમ જ સાચવો','Do not save any shipping address' => 'કોઈપણ શિપિંગ સરનામું સાચવશો નહીં','Company name field for shipping address' => 'શિપિંગ સરનામા માટે કંપનીના નામનું ક્ષેત્ર','Change visibility for the company name field for the shipping address section on the checkout form.' => 'ચેકઆઉટ ફોર્મ પર શિપિંગ સરનામાં વિભાગ માટે કંપનીના નામ ફીલ્ડની દૃશ્યતા બદલો.','If field is set as "optional", which is the default visibility state, no changes will be applied to let other plugins apply any changes they need.' => 'જો ફીલ્ડ &quot;વૈકલ્પિક&quot; તરીકે સેટ કરેલ હોય, જે ડિફોલ્ટ દૃશ્યતા સ્થિતિ છે, તો અન્ય પ્લગઇન્સને જરૂરી કોઈપણ ફેરફારો લાગુ કરવા દેવા માટે કોઈ ફેરફારો લાગુ કરવામાં આવશે નહીં.','Hidden (remove field)' => 'છુપાયેલ (ક્ષેત્ર દૂર કરો)','Optional' => 'વૈકલ્પિક','Required' => 'જરૂરી','Add shipping phone field to the checkout form.' => 'ચેકઆઉટ ફોર્મમાં શિપિંગ ફોન ફીલ્ડ ઉમેરો.','Choose in which step to display the shipping phone field.' => 'શિપિંગ ફોન ફીલ્ડ કયા પગલામાં પ્રદર્શિત કરવું તે પસંદ કરો.','Contact step' => 'સંપર્ક પગલું','Billing phone' => 'બિલિંગ ફોન','Add billing phone field to the checkout form.' => 'ચેકઆઉટ ફોર્મમાં બિલિંગ ફોન ફીલ્ડ ઉમેરો.','Choose in which step to display the billing phone field.' => 'બિલિંગ ફોન ફીલ્ડ કયા પગલામાં પ્રદર્શિત કરવું તે પસંદ કરો.','Show country code beside the flag' => 'ધ્વજની બાજુમાં દેશનો કોડ બતાવો','Show an example of a valid phone number inside phone fields' => 'ફોન ફીલ્ડમાં માન્ય ફોન નંબરનું ઉદાહરણ બતાવો.','Do not change placeholders' => 'પ્લેસહોલ્ડર બદલશો નહીં','Show if not defined' => 'જો વ્યાખ્યાયિત ન હોય તો બતાવો','Always show' => 'હંમેશા બતાવો','Order notes' => 'ઓર્ડર નોંધો','Define the visibility of the additional order notes field.' => 'વધારાના ઓર્ડર નોટ્સ ફીલ્ડની દૃશ્યતા વ્યાખ્યાયિત કરો.','Gift options' => 'ભેટ વિકલ્પો','Allow customers to add a gift message and other gift related options to the order.' => 'ગ્રાહકોને ઓર્ડરમાં ભેટ સંદેશ અને અન્ય ભેટ સંબંધિત વિકલ્પો ઉમેરવાની મંજૂરી આપો.','Display the gift message as part of the order details table instead of a separate section' => 'ભેટ સંદેશને અલગ વિભાગને બદલે ઓર્ડર વિગતો કોષ્ટકના ભાગ રૂપે દર્શાવો','This option affects the order confirmation page (thank you page) and order details on account pages, emails and packing slips.' => 'આ વિકલ્પ ઓર્ડર કન્ફર્મેશન પેજ (આભાર પેજ) અને એકાઉન્ટ પેજ, ઇમેઇલ અને પેકિંગ સ્લિપ પર ઓર્ડર વિગતોને અસર કરે છે.','Account matching' => 'એકાઉન્ટ મેચિંગ','Enable the account matching feature' => 'એકાઉન્ટ મેચિંગ સુવિધા સક્ષમ કરો','Associate the guest customer\'s orders with their existing account when an account already exists with the customer\'s contact details.' => 'જ્યારે ગ્રાહકની સંપર્ક વિગતો સાથે એકાઉન્ટ પહેલેથી જ અસ્તિત્વમાં હોય ત્યારે મહેમાન ગ્રાહકના ઓર્ડરને તેમના હાલના એકાઉન્ટ સાથે સાંકળો.','Display message when an account exists with the email address provided' => 'જ્યારે આપેલા ઇમેઇલ સરનામાં સાથે કોઈ એકાઉન્ટ અસ્તિત્વમાં હોય ત્યારે સંદેશ પ્રદર્શિત કરો','Replaces the account creation fields with a notification and option to log in. In some contexts, it might be recommended to leave this option disabled to protect the privacy of customers.' => 'એકાઉન્ટ બનાવવાના ફીલ્ડ્સને સૂચના અને લોગ ઇન કરવાના વિકલ્પથી બદલે છે. કેટલાક સંદર્ભોમાં, ગ્રાહકોની ગોપનીયતાને સુરક્ષિત રાખવા માટે આ વિકલ્પને અક્ષમ રાખવાની ભલામણ કરવામાં આવી શકે છે.','Dashboard' => 'ડેશબોર્ડ','Integrations' => 'એકીકરણ','License keys' => 'લાઇસન્સ કીઓ','Visit our website for more information about our plugins and add-ons.' => 'અમારા પ્લગઇન્સ અને એડ-ઓન્સ વિશે વધુ માહિતી માટે અમારી વેબસાઇટની મુલાકાત લો.','Order pay page' => 'ઓર્ડર ચુકવણી પૃષ્ઠ','Order pay' => 'ઓર્ડર પે','Enable order pay page optimizations' => 'ઓર્ડર પે પેજ ઑપ્ટિમાઇઝેશન સક્ષમ કરો','Changes the layout of order pay page for existing orders pending payment from the customer.' => 'ગ્રાહક પાસેથી ચુકવણી બાકી હોય તેવા હાલના ઓર્ડર માટે ઓર્ડર પે પેજના લેઆઉટમાં ફેરફાર કરે છે.','Add widget areas to the order pay page' => 'ઓર્ડર પે પેજ પર વિજેટ વિસ્તારો ઉમેરો','These widget areas are used to add trust symbols and trust badges on the order pay page.' => 'આ વિજેટ વિસ્તારોનો ઉપયોગ ઓર્ડર પે પેજ પર ટ્રસ્ટ સિમ્બોલ અને ટ્રસ્ટ બેજ ઉમેરવા માટે થાય છે.','Thank you page & order details layout' => 'આભાર પેજ અને ઓર્ડર વિગતો લેઆઉટ','Order details optimizations' => 'ઓર્ડર વિગતો ઑપ્ટિમાઇઝેશન','Enable thank you page and order details optimizations' => 'આભાર પૃષ્ઠ અને ઓર્ડર વિગતો ઑપ્ટિમાઇઝેશન સક્ષમ કરો','Changes the layout of order details on the thank you page and account pages.' => 'આભાર પૃષ્ઠ અને એકાઉન્ટ પૃષ્ઠો પર ઓર્ડર વિગતોના લેઆઉટમાં ફેરફાર કરે છે.','Enable order details customizations on email notifications' => 'ઇમેઇલ સૂચનાઓ પર ઓર્ડર વિગતો કસ્ટમાઇઝેશન સક્ષમ કરો','Display new sections and change order of sections on email notifications. Styles of order details on email notifications remain unchanged.' => 'ઇમેઇલ સૂચનાઓ પર નવા વિભાગો દર્શાવો અને વિભાગોનો ક્રમ બદલો. ઇમેઇલ સૂચનાઓ પર ઓર્ડર વિગતોની શૈલીઓ યથાવત રહે છે.','Thank you page' => 'આભાર પાનું','These options affect the thank you page, also known as order received or order confirmation pages.' => 'આ વિકલ્પો આભાર પૃષ્ઠને અસર કરે છે, જેને ઓર્ડર પ્રાપ્ત અથવા ઓર્ડર પુષ્ટિ પૃષ્ઠો તરીકે પણ ઓળખવામાં આવે છે.','Order details layout' => 'ઓર્ડર વિગતો લેઆઉટ','Display the order details with wide layout on the thank you page' => 'આભાર પૃષ્ઠ પર વિશાળ લેઆઉટ સાથે ઓર્ડર વિગતો દર્શાવો.','Add widget areas to the thank you page' => 'આભાર પૃષ્ઠ પર વિજેટ વિસ્તારો ઉમેરો','These widget areas are used to add trust symbols and trust badges on the thank you page.' => 'આ વિજેટ વિસ્તારોનો ઉપયોગ આભાર પૃષ્ઠ પર ટ્રસ્ટ પ્રતીકો અને ટ્રસ્ટ બેજ ઉમેરવા માટે થાય છે.','Order actions' => 'ક્રિયાઓનો ક્રમ આપો','Choose in which position to display the order actions.' => 'ઓર્ડર ક્રિયાઓ કઈ સ્થિતિમાં પ્રદર્શિત કરવી તે પસંદ કરો.','Inside the order overview' => 'ઓર્ડર ઝાંખીની અંદર','After the order overview' => 'ઓર્ડર ઝાંખી પછી','After order sections' => 'ઓર્ડર વિભાગો પછી','Order status' => 'ઓર્ડર સ્થિતિ','Display the order status progress bar' => 'ઓર્ડર સ્ટેટસ પ્રોગ્રેસ બાર દર્શાવો','Choose in which position to display the section.' => 'વિભાગ કઈ સ્થિતિમાં પ્રદર્શિત કરવો તે પસંદ કરો.','After the order overview and payment instructions' => 'ઓર્ડર ઝાંખી અને ચુકવણી સૂચનાઓ પછી','Before the order items section' => 'ઓર્ડર વસ્તુઓ વિભાગ પહેલાં','Inside the order items section' => 'ઓર્ડર આઇટમ્સ વિભાગની અંદર','After the order items section' => 'ઓર્ડર વસ્તુઓ વિભાગ પછી','On the sidebar' => 'સાઇડબાર પર','Order downloads' => 'ડાઉનલોડ્સનો ઓર્ડર આપો','Gift message' => 'ભેટ સંદેશ','Tools' => 'સાધનો','Troubleshooting' => 'મુશ્કેલીનિવારણ','Debug options' => 'ડીબગ વિકલ્પો','Debug mode' => 'ડીબગ મોડ','Using debug mode affects the website performance. Only use this option while troubleshooting.' => 'ડિબગ મોડનો ઉપયોગ વેબસાઇટના પ્રદર્શનને અસર કરે છે. મુશ્કેલીનિવારણ કરતી વખતે જ આ વિકલ્પનો ઉપયોગ કરો.','Load unminified assets' => 'અનમિનાઇફાઇડ અસ્કયામતો લોડ કરો','Enhanced select fields' => 'સુધારેલ પસંદગીના ક્ષેત્રો','Fix automatic zoom-in on form fields' => 'ફોર્મ ફીલ્ડ્સ પર સ્વચાલિત ઝૂમ-ઇન ઠીક કરો','Set <code>font-size</code> inside form fields to 16px' => 'ફોર્મ ફીલ્ડની અંદર <code>font-size</code> 16px પર સેટ કરો.','Fluid Checkout' => 'પ્રવાહી ચેકઆઉટ','Settings' => 'સેટિંગ્સ','Support' => 'સપોર્ટ','<a target="_blank" href="%s">Upgrade to PRO</a> to unlock more options.' => 'વધુ વિકલ્પો અનલૉક કરવા માટે <a target="_blank" href="%s">PRO પર અપગ્રેડ કરો</a> .','(PRO)' => '(પ્રો)','(experimental)' => '(પ્રાયોગિક)','Please verify your phone number.' => 'કૃપા કરીને તમારો ફોન નંબર ચકાસો.','The Bluehost Plugin' => 'બ્લુહોસ્ટ પ્લગઇન','Custom fields' => 'કસ્ટમ ફીલ્ડ્સ','Enable custom shipping email field' => 'કસ્ટમ શિપિંગ ઇમેઇલ ફીલ્ડ સક્ષમ કરો','When enabled, the shipping email field from the Bluehost plugin will be added to the checkout form.' => 'જ્યારે સક્ષમ હશે, ત્યારે બ્લુહોસ્ટ પ્લગઇનમાંથી શિપિંગ ઇમેઇલ ફીલ્ડ ચેકઆઉટ ફોર્મમાં ઉમેરવામાં આવશે.','Captcha Pro by BestWebSoft' => 'બેસ્ટવેબસોફ્ટ દ્વારા કેપ્ચા પ્રો','Captcha position' => 'કેપ્ચા સ્થિતિ','Define the position to display the captcha section. Some positions might not work depending on the captcha type chosen.' => 'કેપ્ચા વિભાગ પ્રદર્શિત કરવા માટે સ્થિતિ વ્યાખ્યાયિત કરો. પસંદ કરેલા કેપ્ચા પ્રકાર પર આધાર રાખીને કેટલીક સ્થિતિઓ કામ ન પણ કરે.','Selecting a pickup point is required before proceeding.' => 'આગળ વધતા પહેલા પિકઅપ પોઈન્ટ પસંદ કરવું જરૂરી છે.','Pickup point' => 'પિકઅપ પોઈન્ટ','Pickup point not selected yet.' => 'પિકઅપ પોઈન્ટ હજુ પસંદ થયો નથી.','Pickup point:' => 'પિકઅપ પોઈન્ટ:','Mailchimp for WooCommerce' => 'WooCommerce માટે Mailchimp','Subscribe checkbox' => 'સબ્સ્ક્રાઇબ ચેકબોક્સ','Override the position for the subscribe checkbox on the checkout page and always display it on the contact step' => 'ચેકઆઉટ પેજ પર સબ્સ્ક્રાઇબ ચેકબોક્સ માટે સ્થાન ઓવરરાઇડ કરો અને તેને હંમેશા સંપર્ક સ્ટેપ પર પ્રદર્શિત કરો.','Before Shipping Address' => 'શિપિંગ સરનામું પહેલાં','(originally "%s")' => '(મૂળ &quot;%s&quot;)','After Shipping Address' => 'શિપિંગ સરનામું પછી','Selecting a collection point is required when shipping with FermoPoint.' => 'FermoPoint સાથે શિપિંગ કરતી વખતે કલેક્શન પોઈન્ટ પસંદ કરવું જરૂરી છે.','If checked informs typos in email to users. (This feature has been disabled because Fluid Checkout offers the feature. Changes to this option will not take effect)' => 'જો ચેક કરવામાં આવે તો તે વપરાશકર્તાઓને ઇમેઇલમાં ટાઇપિંગ ભૂલોની જાણ કરે છે. (આ સુવિધા અક્ષમ કરવામાં આવી છે કારણ કે ફ્લુઇડ ચેકઆઉટ સુવિધા પ્રદાન કરે છે. આ વિકલ્પમાં ફેરફારો અમલમાં આવશે નહીં)','Enable Mail Check: (disabled feature)' => 'મેઇલ ચેક સક્ષમ કરો: (નિષ્ક્રિય સુવિધા)','Carrier:' => 'વાહક:','Sendinblue - WooCommerce Email Marketing' => 'સેન્ડિનબ્લ્યુ - WooCommerce ઇમેઇલ માર્કેટિંગ','Sign up checkbox position' => 'સાઇન અપ ચેકબોક્સ સ્થિતિ','Move the sign up checkbox to the contact step' => 'સાઇન અપ ચેકબોક્સને સંપર્ક પગલા પર ખસેડો','When enabled, the checkbox will be moved to the contact step independently of the display location defined in the Sendinblue plugin settings.' => 'જ્યારે સક્ષમ હોય, ત્યારે ચેકબોક્સ સેન્ડિનબ્લ્યુ પ્લગઇન સેટિંગ્સમાં વ્યાખ્યાયિત ડિસ્પ્લે સ્થાનથી સ્વતંત્ર રીતે સંપર્ક પગલા પર ખસેડવામાં આવશે.','Theme Betheme' => 'થીમ બેથેમ','Checkout progress' => 'ચેકઆઉટ પ્રગતિ','Output the checkout steps section from Betheme on the checkout, cart and order received pages.' => 'ચેકઆઉટ, કાર્ટ અને ઓર્ડર પ્રાપ્ત થયેલા પૃષ્ઠો પર બેથેમમાંથી ચેકઆઉટ સ્ટેપ્સ વિભાગ આઉટપુટ કરો.','Theme Fennik' => 'થીમ ફેનિક','Breadcrumbs' => 'બ્રેડક્રમ્સ','Output the breadcrumbs section from the Fennik theme when using Fluid Checkout header and footer.' => 'ફ્લુઇડ ચેકઆઉટ હેડર અને ફૂટરનો ઉપયોગ કરતી વખતે ફેનિક થીમમાંથી બ્રેડક્રમ્સ વિભાગ આઉટપુટ કરો.','Theme Go' => 'થીમ ગો','My account layout' => 'મારું એકાઉન્ટ લેઆઉટ','Enable wide layout on "My account" page.' => '&quot;મારું એકાઉન્ટ&quot; પૃષ્ઠ પર પહોળા લેઆઉટને સક્ષમ કરો.','Theme Impreza' => 'થીમ ઇમ્પ્રેઝા','Header' => 'હેડર','Spacing for site header at the checkout page (in pixels)' => 'ચેકઆઉટ પેજ પર સાઇટ હેડર માટે અંતર (પિક્સેલ્સમાં)','Only applicable when using the Impreza theme header at the checkout page.' => 'ચેકઆઉટ પેજ પર ઇમ્પ્રેઝા થીમ હેડરનો ઉપયોગ કરતી વખતે જ લાગુ પડે છે.','Theme Kapee' => 'થીમ કેપી','Output the checkout steps section from the Kapee theme on the checkout, cart and order received pages.' => 'ચેકઆઉટ, કાર્ટ અને ઓર્ડર પ્રાપ્ત પૃષ્ઠો પર કેપી થીમમાંથી ચેકઆઉટ સ્ટેપ્સ વિભાગ આઉટપુટ કરો.','Theme Porto' => 'થીમ પોર્ટો','Output the checkout steps section from the Porto theme on the checkout, cart and order received pages.' => 'ચેકઆઉટ, કાર્ટ અને ઓર્ડર પ્રાપ્ત પૃષ્ઠો પર પોર્ટો થીમમાંથી ચેકઆઉટ સ્ટેપ્સ વિભાગ આઉટપુટ કરો.','Theme Pressmart' => 'થીમ પ્રેસમાર્ટ','Output the checkout steps section from the Pressmart theme on the checkout, cart and order received pages.' => 'ચેકઆઉટ, કાર્ટ અને ઓર્ડર પ્રાપ્ત પૃષ્ઠો પર પ્રેસમાર્ટ થીમમાંથી ચેકઆઉટ સ્ટેપ્સ વિભાગ આઉટપુટ કરો.','Theme The Gem' => 'થીમ ધ જેમ','Output the checkout steps section from The Gem theme when using Fluid Checkout header and footer.' => 'ફ્લુઇડ ચેકઆઉટ હેડર અને ફૂટરનો ઉપયોગ કરતી વખતે ધ જેમ થીમમાંથી ચેકઆઉટ સ્ટેપ્સ વિભાગ આઉટપુટ કરો.','Theme Woodmart' => 'થીમ વૂડમાર્ટ','Output the checkout steps section from the Woodmart theme when using Fluid Checkout header and footer.' => 'ફ્લુઇડ ચેકઆઉટ હેડર અને ફૂટરનો ઉપયોગ કરતી વખતે વુડમાર્ટ થીમમાંથી ચેકઆઉટ સ્ટેપ્સ સેક્શન આઉટપુટ કરો.','Checkout options' => 'ચેકઆઉટ વિકલ્પો','Disable the theme checkout options' => 'થીમ ચેકઆઉટ વિકલ્પોને અક્ષમ કરો','The options display product image, quantity field, remove button and link to product page added by the theme are disabled by default.' => 'થીમ દ્વારા ઉમેરાયેલા પ્રોડક્ટ ઇમેજ, ક્વોન્ટિટી ફીલ્ડ, રિમૂવ બટન અને પ્રોડક્ટ પેજની લિંક ડિફોલ્ટ રૂપે અક્ષમ કરેલા વિકલ્પો છે.','Theme Atomion' => 'થીમ એટોમિયન','Order progress' => 'ઓર્ડર પ્રગતિ','Display order progress from the theme' => 'થીમ પરથી ઓર્ડર પ્રગતિ દર્શાવો','Display the form field labels visible on the page' => 'પૃષ્ઠ પર દૃશ્યમાન ફોર્મ ફીલ્ડ લેબલ્સ દર્શાવો','It is recommended to keep this option enabled for a better user experience.' => 'વધુ સારા વપરાશકર્તા અનુભવ માટે આ વિકલ્પને સક્ષમ રાખવાની ભલામણ કરવામાં આવે છે.','Theme ZK Nito' => 'થીમ ઝેડકે નીટો','Add extra fields to the checkout form' => 'ચેકઆઉટ ફોર્મમાં વધારાના ફીલ્ડ ઉમેરો','Adds an extra shipping email and shipping phone field to the shipping address section.' => 'શિપિંગ સરનામાં વિભાગમાં એક વધારાનો શિપિંગ ઇમેઇલ અને શિપિંગ ફોન ફીલ્ડ ઉમેરે છે.','Go to the home page' => 'હોમ પેજ પર જાઓ','Skip to content' => 'સામગ્રી પર જાઓ','Create an account' => 'ખાતું બનાવો','Log in to your account' => 'તમારા ખાતામાં લોગ ઇન કરો','Already have an account?' => 'પહેલેથી ખાતું છે?','Logged in as %1$s. <a href="%2$s">Log out</a>' => '%1$s તરીકે લોગ ઇન કર્યું. <a href="%2$s">લોગ આઉટ કરો</a>','Your order has a total amount due of %s. No further payment is needed.' => 'તમારા ઓર્ડરની કુલ રકમ %s છે. વધુ કોઈ ચુકવણીની જરૂર નથી.','Close and continue with checkout' => 'બંધ કરો અને ચેકઆઉટ ચાલુ રાખો','Continue' => 'ચાલુ રાખો','Parcel terminal' => 'પાર્સલ ટર્મિનલ','<p>This widget has been replaced by Fluid Checkout. </p><p>When using Fluid Checkout, the checkout page needs to use the original WooCommerce shortcode <code>[woocommerce_checkout]</code> to work properly.</p><p>For more information, visit the Fluid Checkout documentation.</p>' => '<p>આ વિજેટને ફ્લુઇડ ચેકઆઉટ દ્વારા બદલવામાં આવ્યું છે.</p><p> ફ્લુઇડ ચેકઆઉટનો ઉપયોગ કરતી વખતે, ચેકઆઉટ પેજને યોગ્ય રીતે કાર્ય કરવા માટે મૂળ WooCommerce શોર્ટકોડ <code>[woocommerce_checkout]</code> નો ઉપયોગ કરવાની જરૂર છે.</p><p> વધુ માહિતી માટે, ફ્લુઇડ ચેકઆઉટ દસ્તાવેજીકરણની મુલાકાત લો.</p>','Theme The7' => 'થીમ The7','Additional header sections' => 'વધારાના હેડર વિભાગો','Output additional header sections if enabled in the theme settings.' => 'જો થીમ સેટિંગ્સમાં સક્ષમ હોય તો વધારાના હેડર વિભાગો આઉટપુટ કરો.','More information' => 'વધુ માહિતી','Pick a Locker' => 'લોકર પસંદ કરો','Page template' => 'પૃષ્ઠ નમૂનો','Use `Order confirmation` page template for block-based themes' => 'બ્લોક-આધારિત થીમ્સ માટે `ઓર્ડર પુષ્ટિકરણ` પૃષ્ઠ નમૂનાનો ઉપયોગ કરો.','Only applies when using a block-based theme.' => 'બ્લોક-આધારિત થીમનો ઉપયોગ કરતી વખતે જ લાગુ પડે છે.','WooCommerce Stripe Gateway' => 'WooCommerce સ્ટ્રાઇપ ગેટવે','Payment form' => 'ચુકવણી ફોર્મ','Apply styles to the Stripe payment form fields' => 'સ્ટ્રાઇપ પેમેન્ટ ફોર્મ ફીલ્ડમાં સ્ટાઇલ લાગુ કરો','When enabled, Fluid Checkout will apply styles optimized for compatibility with the plugin. You may want to disable this if you are using custom styles for the Stripe payment form fields.' => 'જ્યારે સક્ષમ હોય, ત્યારે ફ્લુઇડ ચેકઆઉટ પ્લગઇન સાથે સુસંગતતા માટે ઑપ્ટિમાઇઝ કરેલી શૈલીઓ લાગુ કરશે. જો તમે સ્ટ્રાઇપ ચુકવણી ફોર્મ ફીલ્ડ્સ માટે કસ્ટમ શૈલીઓનો ઉપયોગ કરી રહ્યા છો, તો તમે આને અક્ષમ કરી શકો છો.','Theme Nyture' => 'થીમ ન્યુચર','Output the checkout steps section from the Nyture theme when using Fluid Checkout.' => 'ફ્લુઇડ ચેકઆઉટનો ઉપયોગ કરતી વખતે Nyture થીમમાંથી ચેકઆઉટ સ્ટેપ્સ વિભાગ આઉટપુટ કરો.','Allows customers to make payments for orders that are either created manually by the store admin or not completed during checkout.' => 'ગ્રાહકોને એવા ઓર્ડર માટે ચુકવણી કરવાની મંજૂરી આપે છે જે સ્ટોર એડમિન દ્વારા મેન્યુઅલી બનાવવામાં આવે છે અથવા ચેકઆઉટ દરમિયાન પૂર્ણ ન થાય.','The plugin WooCommerce Checkout Manager by Quadlayers is not compatible with Fluid Checkout' => 'ક્વાડલેયર્સ દ્વારા WooCommerce ચેકઆઉટ મેનેજર પ્લગઇન ફ્લુઇડ ચેકઆઉટ સાથે સુસંગત નથી.','Company name field for billing address' => 'બિલિંગ સરનામાં માટે કંપની નામ ફીલ્ડ','Change visibility for the company name field for the billing address section on the checkout form.' => 'ચેકઆઉટ ફોર્મ પર બિલિંગ સરનામાં વિભાગ માટે કંપનીના નામ ફીલ્ડની દૃશ્યતા બદલો.','Theme Bookshelf' => 'થીમ બુકશેલ્ફ','Output the checkout steps section from the Bookshelf theme when using Fluid Checkout.' => 'ફ્લુઇડ ચેકઆઉટનો ઉપયોગ કરતી વખતે બુકશેલ્ફ થીમમાંથી ચેકઆઉટ સ્ટેપ્સ વિભાગ આઉટપુટ કરો.','Account password' => 'એકાઉન્ટ પાસવર્ડ','An account will be created with the information provided at checkout when completing the order.' => 'ઓર્ડર પૂર્ણ કરતી વખતે ચેકઆઉટ વખતે આપેલી માહિતીનો ઉપયોગ કરીને એક એકાઉન્ટ બનાવવામાં આવશે.','Choose the style of the progress bar.' => 'પ્રોગ્રેસ બારની શૈલી પસંદ કરો.','Bars' => 'બાર','Theme Ireca' => 'થીમ ઇરેકા','WooCommerce page layout' => 'WooCommerce પેજ લેઆઉટ','Force wide layout on WooCommerce pages' => 'WooCommerce પૃષ્ઠો પર પહોળા લેઆઉટને ફરજિયાત બનાવો','This ensures the content section is not too narrow on WooCommerce pages including checkout, cart, order received, order pay and account pages.' => 'આ ખાતરી કરે છે કે WooCommerce પૃષ્ઠો પર સામગ્રી વિભાગ ખૂબ સાંકડો નથી જેમાં ચેકઆઉટ, કાર્ટ, ઓર્ડર પ્રાપ્ત, ઓર્ડર પે અને એકાઉન્ટ પૃષ્ઠો શામેલ છે.','WooCommerce Smart Coupons' => 'WooCommerce સ્માર્ટ કુપન્સ','Position on checkout page' => 'ચેકઆઉટ પેજ પર સ્થિતિ','Choose where to display the available coupons section on the checkout page.' => 'ચેકઆઉટ પેજ પર ઉપલબ્ધ કૂપન્સ વિભાગ ક્યાં પ્રદર્શિત કરવો તે પસંદ કરો.','Before the progress bar' => 'પ્રગતિ પટ્ટી પહેલાં','After the progress bar' => 'પ્રગતિ પટ્ટી પછી','Before coupon codes section' => 'કૂપન કોડ્સ વિભાગ પહેલાં','Format phone numbers according to the rules for each country.' => 'દરેક દેશના નિયમો અનુસાર ફોન નંબર ફોર્મેટ કરો.','Use precise phone number validation' => 'ચોક્કસ ફોન નંબર માન્યતાનો ઉપયોગ કરો','This is an experimental feature and may not work as expected in all setups. Use it with caution.' => 'આ એક પ્રાયોગિક સુવિધા છે અને બધા સેટઅપમાં અપેક્ષા મુજબ કામ ન પણ કરે. તેનો ઉપયોગ સાવધાનીપૂર્વક કરો.','Phone number validation types used when precise validation is enabled.' => 'ચોક્કસ માન્યતા સક્ષમ હોય ત્યારે ઉપયોગમાં લેવાતા ફોન નંબર માન્યતા પ્રકારો.','Mobile' => 'મોબાઇલ','Fixed line' => 'સ્થિર રેખા','Toll free' => 'ટોલ ફ્રી','Or' => 'અથવા','Contact' => 'સંપર્ક કરો','Multi step' => 'મલ્ટી સ્ટેપ','2 columns' => '2 કૉલમ','1 column' => '1 કૉલમ','Before checkout steps' => 'ચેકઆઉટ પહેલાંના પગલાં','When using the <em>"1 column"</em> checkout layout this option is always set to <em>"Before checkout steps"</em> and also applies to desktop view.' => '<em>&quot;1 કૉલમ&quot;</em> ચેકઆઉટ લેઆઉટનો ઉપયોગ કરતી વખતે આ વિકલ્પ હંમેશા <em>&quot;ચેકઆઉટ પગલાં પહેલાં&quot;</em> પર સેટ હોય છે અને ડેસ્કટોપ વ્યૂ પર પણ લાગુ પડે છે.','Position for the extra order summary section on mobile.' => 'મોબાઇલ પર વધારાના ઓર્ડર સારાંશ વિભાગ માટે સ્થાન.','The option <em>"On the site header"</em> only applies when using the distraction-free header.' => '<em>&quot;સાઇટ હેડર પર&quot;</em> વિકલ્પ ફક્ત વિક્ષેપ-મુક્ત હેડરનો ઉપયોગ કરતી વખતે જ લાગુ પડે છે.','On the site header (requires distraction-free header)' => 'સાઇટ હેડર પર (વિક્ષેપ-મુક્ત હેડરની જરૂર છે)','Initial state for the expansible order summary section on mobile.' => 'મોબાઇલ પર વિસ્તૃત ઓર્ડર સારાંશ વિભાગ માટે પ્રારંભિક સ્થિતિ.','We recommend setting it as <em>expanded</em> for the following countries due to regulatory requirements: <strong>Germany</strong>, <strong>Austria</strong>, <strong>Switzerland</strong>, <strong>Netherlands</strong>, <strong>Poland</strong>, <strong>Belgium</strong> and <strong>France</strong>.' => 'નિયમનકારી આવશ્યકતાઓને કારણે અમે નીચેના દેશો માટે તેને <em>વિસ્તૃત</em> તરીકે સેટ કરવાની ભલામણ કરીએ છીએ: <strong>જર્મની</strong> , <strong>ઑસ્ટ્રિયા</strong> , <strong>સ્વિટ્ઝર્લૅન્ડ</strong> , <strong>નેધરલેન્ડ</strong> , <strong>પોલેન્ડ</strong> , <strong>બેલ્જિયમ</strong> અને <strong>ફ્રાન્સ</strong> .','Collapsed' => 'સંકુચિત','Expanded' => 'વિસ્તૃત','Do not show' => 'બતાવશો નહીં','yes' => 'હા','The shipping phone field may be forced as "required" if the billing address section is displayed after the shipping address section, and the billing phone field is set as "required". This is needed to ensure the shipping address can be copied to the billing address when that option is checked, otherwise the customer might not be able to complete the checkout form.' => 'જો બિલિંગ સરનામું વિભાગ શિપિંગ સરનામાં વિભાગ પછી પ્રદર્શિત થાય, તો શિપિંગ ફોન ફીલ્ડને &quot;જરૂરી&quot; તરીકે ફરજ પાડવામાં આવી શકે છે, અને બિલિંગ ફોન ફીલ્ડ &quot;જરૂરી&quot; તરીકે સેટ કરવામાં આવે છે. જ્યારે તે વિકલ્પ ચેક કરવામાં આવે ત્યારે શિપિંગ સરનામાંને બિલિંગ સરનામાં પર કોપી કરી શકાય તેની ખાતરી કરવા માટે આ જરૂરી છે, અન્યથા ગ્રાહક ચેકઆઉટ ફોર્મ પૂર્ણ કરી શકશે નહીં.','The billing phone field may be forced as "required" if the billing address section is displayed before the shipping address section, and the shipping phone field is set as "required". This is needed to ensure the shipping address can be copied to the billing address when that option is checked, otherwise the customer might not be able to complete the checkout form.' => 'જો બિલિંગ સરનામું વિભાગ શિપિંગ સરનામાં વિભાગ પહેલાં પ્રદર્શિત થાય, તો બિલિંગ ફોન ફીલ્ડને &quot;જરૂરી&quot; તરીકે ફરજ પાડવામાં આવી શકે છે, અને શિપિંગ ફોન ફીલ્ડ &quot;જરૂરી&quot; તરીકે સેટ કરવામાં આવે છે. જ્યારે તે વિકલ્પ ચેક કરવામાં આવે ત્યારે શિપિંગ સરનામાંને બિલિંગ સરનામાં પર કોપી કરી શકાય તેની ખાતરી કરવા માટે આ જરૂરી છે, અન્યથા ગ્રાહક ચેકઆઉટ ફોર્મ પૂર્ણ કરી શકશે નહીં.','Settings profiles' => 'સેટિંગ્સ પ્રોફાઇલ્સ','Settings profile' => 'સેટિંગ્સ પ્રોફાઇલ','You do not have permission to perform this action.' => 'તમને આ ક્રિયા કરવાની પરવાનગી નથી.','You do not have permission to activate plugins.' => 'તમને પ્લગઇન્સ સક્રિય કરવાની પરવાનગી નથી.','Missing plugin.' => 'પ્લગઇન ખૂટે છે.','Plugin activated.' => 'પ્લગઇન સક્રિય કર્યું.','The following changes will be applied:' => 'નીચેના ફેરફારો લાગુ કરવામાં આવશે:','Since Fluid Checkout 5.0, settings are saved differently. Legacy options are still stored in the database to allow downgrades to previous versions if needed.' => 'ફ્લુઇડ ચેકઆઉટ 5.0 થી, સેટિંગ્સ અલગ રીતે સાચવવામાં આવે છે. જો જરૂરી હોય તો પાછલા સંસ્કરણોમાં ડાઉનગ્રેડ કરવાની મંજૂરી આપવા માટે લેગસી વિકલ્પો હજુ પણ ડેટાબેઝમાં સંગ્રહિત છે.','Your store has been running for about 2 weeks on the new settings so you could clean up legacy options stored in the database. Please note that after cleanup, if you need to downgrade to previous versions of the plugin it will use default values for all settings.' => 'તમારો સ્ટોર લગભગ 2 અઠવાડિયાથી નવી સેટિંગ્સ પર ચાલી રહ્યો છે જેથી તમે ડેટાબેઝમાં સંગ્રહિત લેગસી વિકલ્પોને સાફ કરી શકો. કૃપા કરીને નોંધ લો કે સફાઈ પછી, જો તમારે પ્લગઇનના પાછલા સંસ્કરણો પર ડાઉનગ્રેડ કરવાની જરૂર હોય તો તે બધી સેટિંગ્સ માટે ડિફોલ્ટ મૂલ્યોનો ઉપયોગ કરશે.','Fluid Checkout settings cleanup' => 'ફ્લુઇડ ચેકઆઉટ સેટિંગ્સ સફાઈ','Delete leftover options' => 'બાકી રહેલા વિકલ્પો કાઢી નાખો','Help us improve Fluid Checkout' => 'ફ્લુઇડ ચેકઆઉટને બહેતર બનાવવામાં અમારી સહાય કરો','Share anonymous site environment reports with Fluid Checkout to get faster support and help us improve compatibility and measure impact. No customer, user, or sensitive data are included. You can choose what is shared anytime from the Tools settings.' => 'ઝડપી સપોર્ટ મેળવવા અને સુસંગતતા સુધારવા અને અસર માપવામાં અમારી સહાય કરવા માટે ફ્લુઇડ ચેકઆઉટ સાથે અનામી સાઇટ પર્યાવરણ રિપોર્ટ્સ શેર કરો. કોઈ ગ્રાહક, વપરાશકર્તા અથવા સંવેદનશીલ ડેટા શામેલ નથી. તમે ટૂલ્સ સેટિંગ્સમાંથી ગમે ત્યારે શું શેર કરવું તે પસંદ કરી શકો છો.','Enable site environment reports' => 'સાઇટ પર્યાવરણ રિપોર્ટ્સ સક્ષમ કરો','Review settings' => 'સેટિંગ્સની સમીક્ષા કરો','This preview has expired. Reload the admin page to start a new preview.' => 'આ પૂર્વાવલોકન સમાપ્ત થઈ ગયું છે. નવું પૂર્વાવલોકન શરૂ કરવા માટે એડમિન પૃષ્ઠને ફરીથી લોડ કરો.','Preview expired' => 'પ્રીવ્યૂ સમાપ્ત થયો','Orders cannot be placed in the preview.' => 'પ્રીવ્યૂમાં ઓર્ડર આપી શકાતા નથી.','Logging in is not available in the preview.' => 'પ્રીવ્યૂમાં લોગ ઇન કરવાની સુવિધા ઉપલબ્ધ નથી.','Accounts cannot be created in the preview.' => 'પ્રીવ્યૂમાં એકાઉન્ટ્સ બનાવી શકાતા નથી.','Requests to other sites are blocked in the preview.' => 'પૂર્વાવલોકનમાં અન્ય સાઇટ્સની વિનંતીઓ અવરોધિત છે.','Processing…' => 'પ્રક્રિયા કરી રહ્યું છે...','Something went wrong. Please try again.' => 'કંઈક ખોટું થયું. કૃપા કરીને ફરી પ્રયાસ કરો.','Activate plugin' => 'પ્લગઇન સક્રિય કરો','Fluid Checkout PRO - The complete checkout package' => 'ફ્લુઇડ ચેકઆઉટ પ્રો - સંપૂર્ણ ચેકઆઉટ પેકેજ','All PRO features + all add-ons, one price. Design templates, optimized cart and order received pages, account matching, and much more.' => 'બધી PRO સુવિધાઓ + બધા એડ-ઓન્સ, એક કિંમત. ડિઝાઇન ટેમ્પ્લેટ્સ, ઑપ્ટિમાઇઝ્ડ કાર્ટ અને ઓર્ડર પ્રાપ્ત પૃષ્ઠો, એકાઉન્ટ મેચિંગ, અને ઘણું બધું.','Optimized order pay page' => 'ઑપ્ટિમાઇઝ કરેલ ઓર્ડર પે પેજ','Express checkout buttons from supported payment methods' => 'સપોર્ટેડ ચુકવણી પદ્ધતિઓમાંથી એક્સપ્રેસ ચેકઆઉટ બટનો','Delayed account creation' => 'એકાઉન્ટ બનાવવામાં વિલંબ થયો','Address autocomplete with Google Maps APIs' => 'Google Maps API સાથે સરનામું સ્વતઃપૂર્ણ','Multiple saved addresses with the address book' => 'સરનામાં પુસ્તિકા સાથે બહુવિધ સાચવેલા સરનામાં','EU-VAT assistant' => 'EU-VAT સહાયક','Hide this section' => 'આ વિભાગ છુપાવો','Learn more' => 'વધુ જાણો','Get early access' => 'વહેલો પ્રવેશ મેળવો','Activate add-on' => 'એડ-ઓન સક્રિય કરો','Get more out of your checkout journey' => 'તમારી ચેકઆઉટ યાત્રામાંથી વધુ મેળવો','Test API key' => 'API કીનું પરીક્ષણ કરો','Guided setup' => 'માર્ગદર્શિત સેટઅપ','Options' => 'વિકલ્પો','Set up layout and design on the <a href="%s">checkout options</a>.' => '<a href="%s">ચેકઆઉટ વિકલ્પો</a> પર લેઆઉટ અને ડિઝાઇન સેટ કરો.','Enable guest checkout and/or review <a href="%s">customer accounts settings</a>.' => 'મહેમાન ચેકઆઉટ સક્ષમ કરો અને/અથવા <a href="%s">ગ્રાહક એકાઉન્ટ સેટિંગ્સની</a> સમીક્ષા કરો.','Enable optimized <a href="%1$s">cart</a>, <a href="%2$s">thank you</a> and <a href="%3$s">order pay</a> pages.' => 'ઑપ્ટિમાઇઝ્ડ <a href="%1$s">કાર્ટ</a> સક્ષમ કરો, <a href="%2$s">આભાર માનો</a> અને <a href="%3$s">પે પેજ ઓર્ડર કરો</a> .','Enable <a href="%s">address autocomplete</a> from Google Maps.' => 'Google Maps માંથી <a href="%s">સરનામાં સ્વતઃપૂર્ણ</a> સક્ષમ કરો.','Enable multiple saved addresses with <a href="%s">address book</a>.' => '<a href="%s">સરનામાં પુસ્તિકા</a> સાથે બહુવિધ સાચવેલા સરનામાં સક્ષમ કરો.','Check if there are any <a href="%s">integration options</a> available for the theme or other plugins you have installed.' => 'તમે ઇન્સ્ટોલ કરેલી થીમ અથવા અન્ય પ્લગઇન્સ માટે કોઈ <a href="%s">એકીકરણ વિકલ્પો</a> ઉપલબ્ધ છે કે કેમ તે તપાસો.','Get faster support and help us improve compatibility and measure impact. <a href="%s">Enable usage tracking</a> from the tools settings.' => 'ઝડપી સપોર્ટ મેળવો અને સુસંગતતા સુધારવા અને અસર માપવામાં અમારી સહાય કરો. ટૂલ્સ સેટિંગ્સમાંથી <a href="%s">ઉપયોગ ટ્રેકિંગ સક્ષમ કરો</a> .','Missing settings tab.' => 'સેટિંગ્સ ટેબ ખૂટે છે.','Getting started' => 'શરૂઆત કરવી','<strong>Great! Your checkout page is now running on Fluid Checkout.</strong> Here are a few steps to get started:' => '<strong>સરસ! તમારું ચેકઆઉટ પેજ હવે ફ્લુઇડ ચેકઆઉટ પર ચાલી રહ્યું છે.</strong> શરૂઆત કરવા માટે અહીં થોડા પગલાં આપ્યાં છે:','Completed' => 'પૂર્ણ','Preview report data' => 'રિપોર્ટ ડેટાનું પૂર્વાવલોકન કરો','Send now' => 'હમણાં મોકલો','Auto-detect' => 'સ્વતઃ-શોધ','Afrikaans' => 'આફ્રિકન્સ','Albanian' => 'અલ્બેનિયન','Amharic' => 'એમ્હારિક','Arabic' => 'અરબી','Armenian' => 'આર્મેનિયન','Azerbaijani' => 'અઝરબૈજાની','Basque' => 'બાસ્ક','Belarusian' => 'બેલારુશિયન','Bengali' => 'બંગાળી','Bosnian' => 'બોસ્નિયન','Bulgarian' => 'બલ્ગેરિયન','Burmese' => 'બર્મીઝ','Catalan' => 'કતલાન','Chinese' => 'ચાઇનીઝ','Chinese (Simplified)' => 'ચાઇનીઝ (સરળીકૃત)','Chinese (Hong Kong)' => 'ચાઇનીઝ (હોંગકોંગ)','Chinese (Traditional)' => 'ચાઇનીઝ (પરંપરાગત)','Croatian' => 'ક્રોએશિયન','Czech' => 'ચેક','Danish' => 'ડેનિશ','Dutch' => 'ડચ','English' => 'અંગ્રેજી','English (Australian)' => 'અંગ્રેજી (ઓસ્ટ્રેલિયન)','English (Great Britain)' => 'અંગ્રેજી (ગ્રેટ બ્રિટન)','Estonian' => 'એસ્ટોનિયન','Farsi' => 'ફારસી','Finnish' => 'ફિનિશ','Filipino' => 'ફિલિપિનો','French' => 'ફ્રેન્ચ','French (Canadian)' => 'ફ્રેન્ચ (કેનેડિયન)','Galician' => 'ગેલિશિયન','Georgian' => 'જ્યોર્જિયન','German' => 'જર્મન','Greek' => 'ગ્રીક','Gujarati' => 'ગુજરાતી','Hebrew' => 'હીબ્રુ','Hindi' => 'હિન્દી','Hungarian' => 'હંગેરિયન','Icelandic' => 'આઇસલેન્ડિક','Indonesian' => 'ઇન્ડોનેશિયન','Italian' => 'ઇટાલિયન','Japanese' => 'જાપાનીઝ','Kannada' => 'કન્નડ','Kazakh' => 'કઝાક','Khmer' => 'ખ્મેર','Korean' => 'કોરિયન','Kyrgyz' => 'કિર્ગીઝ','Lao' => 'લાઓ','Latvian' => 'લાતવિયન','Lithuanian' => 'લિથુનિયન','Macedonian' => 'મેસેડોનિયન','Malay' => 'મલય','Malayalam' => 'મલયાલમ','Marathi' => 'મરાઠી','Mongolian' => 'મોંગોલિયન','Nepali' => 'નેપાળી','Norwegian' => 'નોર્વેજીયન','Polish' => 'પોલિશ','Portuguese' => 'પોર્ટુગીઝ','Portuguese (Brazil)' => 'પોર્ટુગીઝ (બ્રાઝિલ)','Portuguese (Portugal)' => 'પોર્ટુગીઝ (પોર્ટુગલ)','Punjabi' => 'પંજાબી','Romanian' => 'રોમાનિયન','Russian' => 'રશિયન','Serbian' => 'સર્બિયન','Sinhalese' => 'સિંહાલી','Slovak' => 'સ્લોવાક','Slovenian' => 'સ્લોવેનિયન','Spanish' => 'સ્પેનિશ','Spanish (Latin America)' => 'સ્પેનિશ (લેટિન અમેરિકા)','Swahili' => 'સ્વાહિલી','Swedish' => 'સ્વીડિશ','Tamil' => 'તમિલ','Telugu' => 'તેલુગુ','Thai' => 'થાઈ','Turkish' => 'ટર્કિશ','Ukrainian' => 'યુક્રેનિયન','Urdu' => 'ઉર્દુ','Vietnamese' => 'વિયેતનામીસ','Zulu' => 'ઝુલુ','Google address autocomplete' => 'ગુગલ સરનામું સ્વતઃપૂર્ણ','Google Places API version' => 'ગૂગલ પ્લેસ API વર્ઝન','Choose which version of the Google Places API to use. We recommend moving to the new Places API as soon as possible.' => 'Google Places API નું કયું સંસ્કરણ વાપરવું તે પસંદ કરો. અમે શક્ય તેટલી વહેલી તકે નવા Places API પર જવાની ભલામણ કરીએ છીએ.','We recommend using "Places API (New)" as effective March 1, 2025, Google will move the "Places API (Legacy)" version into Legacy status, meaning you will no longer be able to enable this service for new API keys and that that version of the API will eventually not be available anymore. Existing accounts already using the Legacy API may continue to work without disruptions.' => 'અમે 1 માર્ચ, 2025 થી &quot;Places API (નવું)&quot; નો ઉપયોગ કરવાની ભલામણ કરીએ છીએ, કારણ કે Google &quot;Places API (લેગસી)&quot; સંસ્કરણને લેગસી સ્થિતિમાં ખસેડશે, જેનો અર્થ એ છે કે તમે હવે નવી API કી માટે આ સેવાને સક્ષમ કરી શકશો નહીં અને API નું તે સંસ્કરણ આખરે હવે ઉપલબ્ધ રહેશે નહીં. લેગસી API નો ઉપયોગ કરી રહેલા હાલના એકાઉન્ટ્સ કોઈપણ વિક્ષેપો વિના કાર્ય કરવાનું ચાલુ રાખી શકે છે.','(Recommended)' => '(ભલામણ કરેલ)','Google API key' => 'ગૂગલ API કી','Paste your Google API key and use the test button to confirm it works for this website. Make sure the key is valid and allowed for your domain, otherwise the address field might get blocked preventing customers from completing their orders.' => 'તમારી Google API કી પેસ્ટ કરો અને આ વેબસાઇટ માટે તે કામ કરે છે તેની ખાતરી કરવા માટે ટેસ્ટ બટનનો ઉપયોગ કરો. ખાતરી કરો કે કી માન્ય છે અને તમારા ડોમેન માટે માન્ય છે, નહીં તો સરનામાં ફીલ્ડ બ્લોક થઈ શકે છે અને ગ્રાહકો તેમના ઓર્ડર પૂર્ણ કરી શકતા નથી.','Enable Google address autocomplete' => 'Google સરનામું સ્વતઃપૂર્ણ સક્ષમ કરો','Enable address autocompletion using the Google Maps APIs.' => 'Google Maps API નો ઉપયોગ કરીને સરનામાં સ્વતઃપૂર્ણતા સક્ષમ કરો.','Google API language' => 'ગૂગલ API ભાષા','This language will be used to display the Google Places API address suggestions and addresses will also be autocompleted in this language.' => 'આ ભાષાનો ઉપયોગ Google Places API સરનામાં સૂચનો પ્રદર્શિત કરવા માટે કરવામાં આવશે અને સરનામાં પણ આ ભાષામાં સ્વતઃપૂર્ણ થશે.','Result types' => 'પરિણામ પ્રકારો','Leave empty to accept any type of results, which usually yields better matching results. <a href="%s" target="_blank">See documentation for more details</a>. <br>Select up to 5 types of address search results to return on address autocomplete fields. <br>Visit the Google Maps documentation to learn more about the <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">supported types</a>.' => 'કોઈપણ પ્રકારના પરિણામો સ્વીકારવા માટે ખાલી છોડી દો, જે સામાન્ય રીતે વધુ સારા મેળ ખાતા પરિણામો આપે છે. <a href="%s" target="_blank">વધુ વિગતો માટે દસ્તાવેજીકરણ જુઓ</a> .<br> સરનામાં સ્વતઃપૂર્ણ ક્ષેત્રો પર પાછા ફરવા માટે 5 પ્રકારના સરનામાં શોધ પરિણામો પસંદ કરો.<br> <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">સપોર્ટેડ પ્રકારો</a> વિશે વધુ જાણવા માટે Google Maps દસ્તાવેજીકરણની મુલાકાત લો.','Result types (Legacy API)' => 'પરિણામ પ્રકારો (લેગસી API)','Which type of address search results to return when using Places API (Legacy). <br>Visit the documentation of the Legacy Google Places API to learn more about the <a href="https://developers.google.com/maps/documentation/places/web-service/supported_types#table3" target="_blank">supported types</a>.' => 'Places API (લેગસી) નો ઉપયોગ કરતી વખતે કયા પ્રકારના સરનામાં શોધ પરિણામો પરત કરવા.<br> <a href="https://developers.google.com/maps/documentation/places/web-service/supported_types#table3" target="_blank">સપોર્ટેડ પ્રકારો</a> વિશે વધુ જાણવા માટે Legacy Google Places API ના દસ્તાવેજીકરણની મુલાકાત લો.','Company fields' => 'કંપની ક્ષેત્રો','Enable autocomplete for the company name if available' => 'જો ઉપલબ્ધ હોય તો કંપનીના નામ માટે સ્વતઃપૂર્ણ ચાલુ કરો','Enable autocompletion of the company field with the company name information when returned from the Google Maps APIs.' => 'Google Maps API માંથી પરત કરવામાં આવે ત્યારે કંપનીના નામની માહિતી સાથે કંપની ફીલ્ડની સ્વતઃપૂર્ણતા સક્ષમ કરો.','Business search' => 'વ્યવસાય શોધ','Enable search for businesses in the company field' => 'કંપની ક્ષેત્રમાં વ્યવસાયો માટે શોધ સક્ષમ કરો','Enable suggestion of addresses associated with a business when typing in the company field, then autocomplete all addresses fields when a business is selected from the suggestions.' => 'કંપની ફીલ્ડમાં ટાઇપ કરતી વખતે વ્યવસાય સાથે સંકળાયેલા સરનામાંના સૂચનને સક્ષમ કરો, પછી સૂચનોમાંથી વ્યવસાય પસંદ કરવામાં આવે ત્યારે બધા સરનામાં ફીલ્ડને સ્વતઃપૂર્ણ કરો.','Company result types' => 'કંપનીના પરિણામના પ્રકારો','Select up to 5 types of address search results to return on autocomplete company fields. <br>Recommended value is <code>establishment</code>, which includes most types of businesses. <br>Leave empty to accept any type of results, including results that are not related to businesses. <br>Visit the Google Maps documentation to learn more about the <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">supported types</a>.' => 'ઓટોકમ્પ્લીટ કંપની ફીલ્ડ પર પાછા ફરવા માટે 5 પ્રકારના સરનામાં શોધ પરિણામો પસંદ કરો.<br> ભલામણ કરેલ મૂલ્ય <code>establishment</code> છે, જેમાં મોટાભાગના પ્રકારના વ્યવસાયોનો સમાવેશ થાય છે.<br> વ્યવસાયો સાથે સંબંધિત ન હોય તેવા પરિણામો સહિત, કોઈપણ પ્રકારના પરિણામો સ્વીકારવા માટે ખાલી છોડી દો.<br> <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">સપોર્ટેડ પ્રકારો</a> વિશે વધુ જાણવા માટે Google Maps દસ્તાવેજીકરણની મુલાકાત લો.','Google logo' => 'ગુગલ લોગો','Show text and logo "Powered by Google"' => '&quot;Google દ્વારા સંચાલિત&quot; ટેક્સ્ટ અને લોગો બતાવો','When checked, the text and logo "Powered by Google" will be displayed at the bottom of the address autocomplete suggestions box.' => 'જ્યારે ચેક કરવામાં આવશે, ત્યારે સરનામાં સ્વતઃપૂર્ણ સૂચનો બોક્સના તળિયે &quot;Powered by Google&quot; ટેક્સ્ટ અને લોગો પ્રદર્શિત થશે.','Brasil API address autocomplete' => 'બ્રાઝિલ API સરનામું સ્વતઃપૂર્ણ','Brasil API' => 'બ્રાઝિલ API','Enable Brasil API address autocomplete for CEP fields' => 'CEP ફીલ્ડ માટે બ્રાઝિલ API સરનામું સ્વતઃપૂર્ણ સક્ષમ કરો','Use Brasil API to retrieve and autofill addresses using the CEP/Postcode field. Only relevant for Brazilian addresses.' => 'CEP/પોસ્ટકોડ ફીલ્ડનો ઉપયોગ કરીને સરનામાં મેળવવા અને ઓટોફિલ કરવા માટે બ્રાઝિલ API નો ઉપયોગ કરો. ફક્ત બ્રાઝિલિયન સરનામાં માટે જ સંબંધિત.','API version' => 'API સંસ્કરણ','Choose which version of the Brasil API CEP method to use.' => 'બ્રાઝિલ API CEP પદ્ધતિના કયા સંસ્કરણનો ઉપયોગ કરવો તે પસંદ કરો.','Address book migration' => 'સરનામાં પુસ્તિકા સ્થળાંતર','WooCommerce addresses' => 'WooCommerce સરનામાં','Copy existing shipping and billing addresses from WooCommerce into the customers\' address book.' => 'WooCommerce માંથી હાલના શિપિંગ અને બિલિંગ સરનામાં ગ્રાહકોની સરનામાં પુસ્તિકામાં કોપી કરો.','Enable the address book feature' => 'સરનામાં પુસ્તિકા સુવિધા સક્ષમ કરો','Allow customers to save multiple addresses and define the default address to be used for shipping and billing.' => 'ગ્રાહકોને બહુવિધ સરનામાં સાચવવાની અને શિપિંગ અને બિલિંગ માટે ઉપયોગમાં લેવાતા ડિફોલ્ટ સરનામાંને વ્યાખ્યાયિત કરવાની મંજૂરી આપો.','Address labels' => 'સરનામાંના લેબલ્સ','Allow customers to add a custom label for each address' => 'ગ્રાહકોને દરેક સરનામાં માટે કસ્ટમ લેબલ ઉમેરવાની મંજૂરી આપો','Address labels make it easier to for customers to distinguish between their saved addresses (ie.: "Mom\'s House"). The address labels are private to the customers, and will not be displayed or printed on the order details page or invoices.' => 'સરનામાંના લેબલ્સ ગ્રાહકો માટે તેમના સાચવેલા સરનામાં (દા.ત.: &quot;મમ્મીનું ઘર&quot;) વચ્ચે તફાવત કરવાનું સરળ બનાવે છે. સરનામાંના લેબલ્સ ગ્રાહકો માટે ખાનગી છે, અને ઓર્ડર વિગતો પૃષ્ઠ અથવા ઇન્વોઇસ પર પ્રદર્શિત અથવા છાપવામાં આવશે નહીં.','Display layout' => 'ડિસ્પ્લે લેઆઉટ','Choose how saved addresses are displayed at checkout and on the cart.' => 'ચેકઆઉટ વખતે અને કાર્ટ પર સાચવેલા સરનામાં કેવી રીતે પ્રદર્શિત થાય તે પસંદ કરો.','Applies at checkout and on the cart. Saved addresses on the account page always use the cards layout.' => 'ચેકઆઉટ અને કાર્ટ પર લાગુ પડે છે. એકાઉન્ટ પેજ પર સેવ કરેલા સરનામાં હંમેશા કાર્ડ લેઆઉટનો ઉપયોગ કરે છે.','Address cards' => 'સરનામાં કાર્ડ્સ','Address list' => 'સરનામાં યાદી','Dropdown field' => 'ડ્રોપડાઉન ફીલ્ડ','Address search' => 'સરનામું શોધ','Show address search filter on frontend when customer has at least this number of saved addresses available.' => 'જ્યારે ગ્રાહક પાસે ઓછામાં ઓછા આટલા સેવ કરેલા સરનામાં ઉપલબ્ધ હોય ત્યારે ફ્રન્ટએન્ડ પર સરનામાં શોધ ફિલ્ટર બતાવો.','Not used when display layout is set to dropdown field.' => 'જ્યારે ડિસ્પ્લે લેઆઉટ ડ્રોપડાઉન ફીલ્ડ પર સેટ હોય ત્યારે ઉપયોગમાં લેવાતું નથી.','Addresses' => 'સરનામાંઓ','Enable cart page optimizations to see more options' => 'વધુ વિકલ્પો જોવા માટે કાર્ટ પેજ ઑપ્ટિમાઇઝેશન સક્ષમ કરો','Sticky order summary' => 'સ્ટીકી ઓર્ડર સારાંશ','Select position where to display the coupon codes section on the cart page. Only applicable when AJAX cart is enabled, and if use of coupon codes are enabled in the WooCommerce settings.' => 'કાર્ટ પેજ પર કૂપન કોડ વિભાગ ક્યાં પ્રદર્શિત કરવો તે સ્થાન પસંદ કરો. ફક્ત ત્યારે જ લાગુ પડે છે જ્યારે AJAX કાર્ટ સક્ષમ હોય, અને જો WooCommerce સેટિંગ્સમાં કૂપન કોડનો ઉપયોગ સક્ષમ હોય.','Layout of cross-sell' => 'ક્રોસ-સેલનો લેઆઉટ','Cross-sells displayed' => 'ક્રોસ-સેલ્સ પ્રદર્શિત','Items' => 'વસ્તુઓ','Cart page optimization' => 'કાર્ટ પેજ ઑપ્ટિમાઇઝેશન','Give your cart the same clear, conversion-focused layout as your checkout.' => 'તમારા કાર્ટને તમારા ચેકઆઉટ જેવો જ સ્પષ્ટ, રૂપાંતર-કેન્દ્રિત લેઆઉટ આપો.','Match the cart layout to the checkout page for a consistent purchase journey.' => 'સતત ખરીદી યાત્રા માટે કાર્ટ લેઆઉટને ચેકઆઉટ પૃષ્ઠ સાથે મેચ કરો.','Keep the cart always updated in the background, no full page reloads when quantities change.' => 'કાર્ટને હંમેશા પૃષ્ઠભૂમિમાં અપડેટ રાખો, જથ્થામાં ફેરફાર થાય ત્યારે આખું પૃષ્ઠ ફરીથી લોડ થતું નથી.','Place coupon codes, shipping, and cross-sells exactly where they convert best.' => 'કૂપન કોડ્સ, શિપિંગ અને ક્રોસ-સેલ્સ બરાબર ત્યાં મૂકો જ્યાં તેઓ શ્રેષ્ઠ રૂપાંતરિત થાય છે.','Keep the order summary visible while scrolling, and add trust symbols where shoppers need reassurance.' => 'સ્ક્રોલ કરતી વખતે ઓર્ડર સારાંશ દૃશ્યમાન રાખો, અને જ્યાં ખરીદદારોને ખાતરીની જરૂર હોય ત્યાં વિશ્વાસ પ્રતીકો ઉમેરો.','Columns' => 'કૉલમ','General styles for the checkout steps, order summary and other sections. Applies to other checkout, cart, thank you (order received), and view order pages.' => 'ચેકઆઉટ પગલાં, ઓર્ડર સારાંશ અને અન્ય વિભાગો માટે સામાન્ય શૈલીઓ. અન્ય ચેકઆઉટ, કાર્ટ, આભાર (ઓર્ડર પ્રાપ્ત થયો), અને ઓર્ડર પૃષ્ઠો જોવા માટે લાગુ પડે છે.','When using the <em>"1 column"</em> layout with the <em>"Split"</em> design template, a right column is shown only if the page sidebar widget area is active (Checkout Sidebar, Cart Sidebar, or Order Received Sidebar). Otherwise the page stays as a single column with Split styles.' => '<em>&quot;સ્પ્લિટ&quot;</em> ડિઝાઇન ટેમ્પ્લેટ સાથે <em>&quot;1 કૉલમ&quot;</em> લેઆઉટનો ઉપયોગ કરતી વખતે, જો પેજ સાઇડબાર વિજેટ વિસ્તાર સક્રિય હોય (ચેકઆઉટ સાઇડબાર, કાર્ટ સાઇડબાર, અથવા ઓર્ડર પ્રાપ્ત સાઇડબાર) તો જ જમણો કૉલમ બતાવવામાં આવે છે. નહિંતર, પેજ સ્પ્લિટ સ્ટાઇલ સાથે એક કૉલમ તરીકે રહે છે.','Split column background' => 'કૉલમ પૃષ્ઠભૂમિને વિભાજિત કરો','Choose a background color for the Split design secondary column. Leave empty to use the order summary background color.' => 'સ્પ્લિટ ડિઝાઇન ગૌણ કૉલમ માટે પૃષ્ઠભૂમિ રંગ પસંદ કરો. ઓર્ડર સારાંશ પૃષ્ઠભૂમિ રંગનો ઉપયોગ કરવા માટે ખાલી છોડી દો.','Page templates' => 'પૃષ્ઠ નમૂનાઓ','Checkout template' => 'ચેકઆઉટ ટેમ્પલેટ','Recommended for fewer distractions at checkout. <a href="https://baymard.com/blog/cart-abandonment" target="_blank">Read the research about cart abandonment</a>.' => 'ચેકઆઉટ વખતે ઓછા વિક્ષેપો માટે ભલામણ કરેલ. <a href="https://baymard.com/blog/cart-abandonment" target="_blank">કાર્ટ છોડી દેવા વિશે સંશોધન વાંચો</a> .','Sticky progress bar' => 'સ્ટીકી પ્રોગ્રેસ બાર','Progress bar style' => 'પ્રગતિ પટ્ટી શૈલી','Order totals' => 'કુલ ઓર્ડર','Background color' => 'પૃષ્ઠભૂમિ રંગ','Action link' => 'ક્રિયા લિંક','Mobile order summary' => 'મોબાઇલ ઓર્ડર સારાંશ','Mobile initial state' => 'મોબાઇલની શરૂઆતની સ્થિતિ','Enable editing cart items at checkout' => 'ચેકઆઉટ વખતે કાર્ટ આઇટમમાં ફેરફાર કરવાનું ચાલુ કરો','Allow customers to change product quantities or remove items directly at the checkout page.' => 'ગ્રાહકોને ચેકઆઉટ પેજ પર સીધા જ ઉત્પાદનની માત્રા બદલવા અથવા વસ્તુઓ દૂર કરવાની મંજૂરી આપો.','Cart item errors' => 'કાર્ટ આઇટમ ભૂલો','Only applicable when coupon code is displayed as a separate section on the checkout or cart pages, and if use of coupon codes are enabled in the WooCommerce settings.' => 'ચેકઆઉટ અથવા કાર્ટ પૃષ્ઠો પર કૂપન કોડ એક અલગ વિભાગ તરીકે પ્રદર્શિત થાય ત્યારે જ લાગુ પડે છે, અને જો WooCommerce સેટિંગ્સમાં કૂપન કોડનો ઉપયોગ સક્ષમ હોય.','Coupon codes position' => 'કૂપન કોડની સ્થિતિ','Apply coupon button' => 'કૂપન બટન લાગુ કરો','Select style of the "apply coupon" button.' => '&quot;કૂપન લાગુ કરો&quot; બટનની શૈલી પસંદ કરો.','Address line 2' => 'સરનામાં લાઇન 2','This setting is shared between the Checkout and Local pickup sections. On the Local pickup section, it also decides whether the Ship/Pickup selector shows inside the shipping method section (before the address) or as a separate section (after).' => 'આ સેટિંગ ચેકઆઉટ અને સ્થાનિક પિકઅપ વિભાગો વચ્ચે શેર કરવામાં આવે છે. સ્થાનિક પિકઅપ વિભાગ પર, તે એ પણ નક્કી કરે છે કે શિપ/પિકઅપ પસંદગીકાર શિપિંગ પદ્ધતિ વિભાગ (સરનામા પહેલા) ની અંદર દેખાય છે કે પછી એક અલગ વિભાગ (પછી) તરીકે.','Customer accounts' => 'ગ્રાહક એકાઉન્ટ્સ','Guest checkout' => 'મહેમાન ચેકઆઉટ','Guest checkout, login, and account creation options from the WooCommerce Accounts settings page. They are managed here for your convenience, and so you can use different values per settings profile.' => 'WooCommerce એકાઉન્ટ્સ સેટિંગ્સ પૃષ્ઠ પરથી ગેસ્ટ ચેકઆઉટ, લોગિન અને એકાઉન્ટ બનાવવાના વિકલ્પો. તમારી સુવિધા માટે તે અહીં મેનેજ કરવામાં આવે છે, અને તેથી તમે દરેક સેટિંગ્સ પ્રોફાઇલ માટે અલગ અલગ મૂલ્યોનો ઉપયોગ કરી શકો છો.','Allow customers to checkout without an account' => 'ગ્રાહકોને એકાઉન્ટ વિના ચેકઆઉટ કરવાની મંજૂરી આપો','<strong>Recommended</strong> so customers are not asked to create an account or log in during checkout, which can lower conversion rates.' => 'ગ્રાહકોને ચેકઆઉટ દરમિયાન એકાઉન્ટ બનાવવા કે લોગ ઇન કરવાનું કહેવામાં ન આવે તે માટે <strong>ભલામણ કરવામાં આવે છે</strong> , જેનાથી રૂપાંતર દર ઘટી શકે છે.','When disabled, customers must log in or create an account to complete the purchase.' => 'જ્યારે અક્ષમ હોય, ત્યારે ગ્રાહકોએ ખરીદી પૂર્ણ કરવા માટે લોગ ઇન કરવું અથવા એકાઉન્ટ બનાવવું આવશ્યક છે.','Login at checkout' => 'ચેકઆઉટ વખતે લોગિન કરો','Enable log-in during checkout' => 'ચેકઆઉટ દરમિયાન લોગ-ઇન સક્ષમ કરો','Show a link for returning customers to log in from the checkout page.' => 'પરત ફરતા ગ્રાહકોને ચેકઆઉટ પેજ પરથી લોગ ઇન કરવા માટે એક લિંક બતાવો.','Account creation' => 'એકાઉન્ટ બનાવવું','Allow customers to create an account during checkout' => 'ચેકઆઉટ દરમિયાન ગ્રાહકોને એકાઉન્ટ બનાવવાની મંજૂરી આપો','Customers can create an account before placing their order.' => 'ગ્રાહકો ઓર્ડર આપતા પહેલા એકાઉન્ટ બનાવી શકે છે.','Allow customers to create an account from the My account page' => 'ગ્રાહકોને મારું એકાઉન્ટ પેજ પરથી એકાઉન્ટ બનાવવાની મંજૂરી આપો.','Customers can register a new account from the My account page.' => 'ગ્રાહકો માય એકાઉન્ટ પેજ પરથી નવું એકાઉન્ટ રજીસ્ટર કરાવી શકે છે.','Username' => 'વપરાશકર્તા નામ','Generate from customer\'s name' => 'ગ્રાહકના નામ પરથી જનરેટ કરો','<strong>Recommended</strong> so customers are not asked to choose a username during checkout, which can lower conversion rates.' => 'ગ્રાહકોને ચેકઆઉટ દરમિયાન વપરાશકર્તાનામ પસંદ કરવાનું કહેવામાં ન આવે તે માટે <strong>ભલામણ કરવામાં આવે છે</strong> , જે રૂપાંતર દર ઘટાડી શકે છે.','A username is generated from the customer name, or from the email address when a name cannot be used.' => 'ગ્રાહકના નામ પરથી અથવા જ્યારે નામનો ઉપયોગ કરી શકાતો નથી ત્યારે ઇમેઇલ સરનામાં પરથી વપરાશકર્તા નામ જનરેટ થાય છે.','Password' => 'પાસવર્ડ','Send password setup link' => 'પાસવર્ડ સેટઅપ લિંક મોકલો','<strong>Recommended</strong> so customers are not asked to set a password during checkout, which can lower conversion rates.' => 'ગ્રાહકોને ચેકઆઉટ દરમિયાન પાસવર્ડ સેટ કરવાનું કહેવામાં ન આવે તે માટે <strong>ભલામણ કરવામાં આવે છે</strong> , જે રૂપાંતર દર ઘટાડી શકે છે.','Customers receive an email to create their password securely.' => 'ગ્રાહકોને સુરક્ષિત રીતે પોતાનો પાસવર્ડ બનાવવા માટે એક ઇમેઇલ પ્રાપ્ત થાય છે.','Let registered customers complete checkout without logging in and associate the order with their existing account when contact details match.' => 'નોંધાયેલા ગ્રાહકોને લોગ ઇન કર્યા વિના ચેકઆઉટ પૂર્ણ કરવા દો અને સંપર્ક વિગતો મેળ ખાતી વખતે ઓર્ડરને તેમના હાલના એકાઉન્ટ સાથે સાંકળો.','Existing account message' => 'હાલના એકાઉન્ટ સંદેશ','Let customers create an account after placing their order, from the thank you page.' => 'ઓર્ડર આપ્યા પછી ગ્રાહકોને આભાર પૃષ્ઠ પરથી એકાઉન્ટ બનાવવા દો.','Options in this section are available when guest checkout and account matching are enabled. Enable both features above to configure delayed account creation.' => 'જ્યારે ગેસ્ટ ચેકઆઉટ અને એકાઉન્ટ મેચિંગ સક્ષમ હોય ત્યારે આ વિભાગમાં વિકલ્પો ઉપલબ્ધ હોય છે. વિલંબિત એકાઉન્ટ બનાવટને ગોઠવવા માટે ઉપરોક્ત બંને સુવિધાઓ સક્ષમ કરો.','Enable delayed account creation' => 'વિલંબિત એકાઉન્ટ બનાવટ સક્ષમ કરો','Enable delayed account creation when both guest checkout and account matching are enabled.' => 'જ્યારે ગેસ્ટ ચેકઆઉટ અને એકાઉન્ટ મેચિંગ બંને સક્ષમ હોય ત્યારે વિલંબિત એકાઉન્ટ બનાવવાનું સક્ષમ કરો.','Section position' => 'વિભાગની સ્થિતિ','Before customer details section' => 'ગ્રાહક વિગતો વિભાગ પહેલાં','After customer details section' => 'ગ્રાહક વિગતો વિભાગ પછી','Account creation benefits' => 'એકાઉન્ટ બનાવવાના ફાયદા','Leaving the field empty will display the default text.' => 'ફીલ્ડ ખાલી રાખવાથી ડિફોલ્ટ ટેક્સ્ટ પ્રદર્શિત થશે.','Inline buttons' => 'ઇનલાઇન બટનો','Required fields' => 'જરૂરી ક્ષેત્રો','Enable gift message fields at checkout' => 'ચેકઆઉટ વખતે ભેટ સંદેશ ફીલ્ડ સક્ષમ કરો','Expanded gift message' => 'વિસ્તૃત ભેટ સંદેશ','Display gift message field always expanded' => 'ભેટ સંદેશ ક્ષેત્ર હંમેશા વિસ્તૃત દર્શાવો','Gift message in order details' => 'ઓર્ડર વિગતો માટે ભેટ સંદેશ','No integrations available at the moment on this section. The options related to each plugin and theme will only appear here when that plugin or theme is activated.' => 'આ વિભાગમાં હાલમાં કોઈ એકીકરણ ઉપલબ્ધ નથી. દરેક પ્લગઇન અને થીમ સંબંધિત વિકલ્પો ફક્ત ત્યારે જ અહીં દેખાશે જ્યારે તે પ્લગઇન અથવા થીમ સક્રિય થશે.','Phone fields' => 'ફોન ફીલ્ડ્સ','Field visibility' => 'ક્ષેત્ર દૃશ્યતા','Field position' => 'ક્ષેત્રની સ્થિતિ','Phone country code & validation' => 'ફોન દેશ કોડ અને માન્યતા','Country' => 'દેશ','Enable country on phone fields' => 'ફોન ફીલ્ડ પર દેશ સક્ષમ કરો','Filter countries for shipping or billing' => 'શિપિંગ અથવા બિલિંગ માટે દેશો ફિલ્ટર કરો','Limit the country selector on each phone field to the countries allowed for shipping or billing on your store.' => 'દરેક ફોન ફીલ્ડ પર દેશ પસંદગીકારને તમારા સ્ટોર પર શિપિંગ અથવા બિલિંગ માટે માન્ય દેશો સુધી મર્યાદિત કરો.','Validation' => 'માન્યતા','Enable simple validation based on country rules' => 'દેશના નિયમોના આધારે સરળ માન્યતા સક્ષમ કરો','Checks that the phone number is valid for the selected country, including country code and length.' => 'દેશ કોડ અને લંબાઈ સહિત, પસંદ કરેલા દેશ માટે ફોન નંબર માન્ય છે કે નહીં તે તપાસે છે.','Stricter check that the number is a valid mobile, fixed line, or other accepted type for the selected country. May reject some valid numbers.' => 'પસંદ કરેલા દેશ માટે નંબર માન્ય મોબાઇલ, ફિક્સ્ડ લાઇન અથવા અન્ય સ્વીકૃત પ્રકારનો છે કે નહીં તે વધુ કડક રીતે તપાસો. કેટલાક માન્ય નંબરો નકારી શકાય છે.','Validation types' => 'માન્યતા પ્રકારો','Placeholders' => 'પ્લેસહોલ્ડર્સ','No license keys to manage at the moment. License keys will appear here when a licensed Fluid Checkout plugin or add-on is active.' => 'હાલમાં મેનેજ કરવા માટે કોઈ લાઇસન્સ કી નથી. જ્યારે લાઇસન્સ પ્રાપ્ત ફ્લુઇડ ચેકઆઉટ પ્લગઇન અથવા એડ-ઓન સક્રિય હશે ત્યારે લાઇસન્સ કી અહીં દેખાશે.','Default delivery type' => 'ડિફૉલ્ટ ડિલિવરી પ્રકાર','Choose which delivery type will be selected by default.' => 'ડિફૉલ્ટ રૂપે કયો ડિલિવરી પ્રકાર પસંદ કરવામાં આવશે તે પસંદ કરો.','Shipping zone fields' => 'શિપિંગ ઝોન ક્ષેત્રો','Choose which fields will be displayed for the local pickup shipping zone filter fields. Leave empty to show all available options.' => 'સ્થાનિક પિકઅપ શિપિંગ ઝોન ફિલ્ટર ફીલ્ડ માટે કયા ફીલ્ડ્સ પ્રદર્શિત થશે તે પસંદ કરો. બધા ઉપલબ્ધ વિકલ્પો બતાવવા માટે ખાલી છોડી દો.','These fields will be displayed as a filter for the local pickup shipping methods. Some fields might still appear at checkout when not selected here, if compatible plugins require them to work properly.' => 'આ ફીલ્ડ્સ સ્થાનિક પિકઅપ શિપિંગ પદ્ધતિઓ માટે ફિલ્ટર તરીકે પ્રદર્શિત થશે. જો સુસંગત પ્લગઇન્સ માટે તેમને યોગ્ય રીતે કાર્ય કરવાની જરૂર હોય, તો કેટલાક ફીલ્ડ્સ અહીં પસંદ ન કર્યા પછી પણ ચેકઆઉટ પર દેખાઈ શકે છે.','Order shipping address' => 'ઓર્ડર શિપિંગ સરનામું','Order pay page optimization' => 'ઓર્ડર પે પેજ ઑપ્ટિમાઇઝેશન','Give unpaid orders the same clear, conversion-focused layout as checkout.' => 'ચૂકવણી ન કરેલા ઓર્ડરને ચેકઆઉટ જેવો જ સ્પષ્ટ, રૂપાંતર-કેન્દ્રિત લેઆઉટ આપો.','Optimize the layout of the order pay page for orders pending payment.' => 'બાકી ચુકવણી માટે ઓર્ડર પે પેજના લેઆઉટને ઑપ્ટિમાઇઝ કરો.','Match the order pay experience to your checkout for a consistent purchase journey.' => 'ખરીદીની સતત યાત્રા માટે ઓર્ડર પે અનુભવને તમારા ચેકઆઉટ સાથે મેચ કરો.','Add trust symbols and badges where shoppers need reassurance before paying.' => 'ખરીદદારોને ચૂકવણી કરતા પહેલા ખાતરીની જરૂર હોય ત્યાં વિશ્વાસ પ્રતીકો અને બેજ ઉમેરો.','Thank you page optimization' => 'પેજ ઑપ્ટિમાઇઝેશન માટે આભાર','Make the thank you page and order details clearer for customers after they buy.' => 'ગ્રાહકો ખરીદી કર્યા પછી તેમના માટે આભાર પાનું અને ઓર્ડરની વિગતો વધુ સ્પષ્ટ બનાવો.','Optimize the thank you page and account order details with a clearer layout.' => 'સ્પષ્ટ લેઆઉટ સાથે આભાર પૃષ્ઠ અને એકાઉન્ટ ઓર્ડર વિગતોને ઑપ્ટિમાઇઝ કરો.','Show order status progress, actions, downloads, and notes where they make sense.' => 'ઓર્ડર સ્થિતિ પ્રગતિ, ક્રિયાઓ, ડાઉનલોડ્સ અને નોંધો જ્યાં અર્થપૂર્ણ હોય ત્યાં બતાવો.','Customize order details sections on email notifications.' => 'ઇમેઇલ સૂચનાઓ પર ઓર્ડર વિગતો વિભાગોને કસ્ટમાઇઝ કરો.','Add trust symbols and badges where shoppers need reassurance after purchase.' => 'ખરીદી કર્યા પછી ખરીદદારોને ખાતરીની જરૂર હોય ત્યાં વિશ્વાસના પ્રતીકો અને બેજ ઉમેરો.','Email notifications' => 'ઇમેઇલ સૂચનાઓ','Enable thank you page and order details optimizations to see more options' => 'વધુ વિકલ્પો જોવા માટે આભાર પેજ અને ઓર્ડર વિગતો ઑપ્ટિમાઇઝેશન ચાલુ કરો','Use wide layout on thank you page' => 'આભાર પૃષ્ઠ પર પહોળા લેઆઉટનો ઉપયોગ કરો','These options affect the thank you page, view order details on account pages and on email notifications.' => 'આ વિકલ્પો આભાર પૃષ્ઠને અસર કરે છે, એકાઉન્ટ પૃષ્ઠો પર અને ઇમેઇલ સૂચનાઓ પર ઓર્ડર વિગતો જુઓ.','Save settings' => 'સેટિંગ્સ સાચવો','Docs' => 'દસ્તાવેજો','Cart' => 'કાર્ટ','Thank you' => 'આભાર','Address autocomplete' => 'સરનામું સ્વતઃપૂર્ણ','Trust badges' => 'ટ્રસ્ટ બેજ','You do not have permission to save these settings.' => 'તમારી પાસે આ સેટિંગ્સ સાચવવાની પરવાનગી નથી.','Invalid save request.' => 'અમાન્ય સાચવવાની વિનંતી.','Your settings have been saved.' => 'તમારી સેટિંગ્સ સાચવવામાં આવી છે.','Saving...' => 'સાચવી રહ્યું છે...','Settings could not be saved. Please try again.' => 'સેટિંગ્સ સાચવી શકાઈ નથી. કૃપા કરીને ફરી પ્રયાસ કરો.','Dismiss notice' => 'સૂચના કાઢી નાખો','Open settings menu' => 'સેટિંગ્સ મેનૂ ખોલો','Close settings menu' => 'સેટિંગ્સ મેનૂ બંધ કરો','Preview' => 'પૂર્વાવલોકન','Expand preview' => 'પ્રીવ્યૂ વિસ્તૃત કરો','Collapse preview' => 'પૂર્વાવલોકન સંકુચિત કરો','Show header and footer' => 'હેડર અને ફૂટર બતાવો','Hide header and footer' => 'હેડર અને ફૂટર છુપાવો','Page preview' => 'પૃષ્ઠ પૂર્વાવલોકન','Preview viewport' => 'વ્યૂપોર્ટનું પૂર્વાવલોકન કરો','Tablet' => 'ટેબ્લેટ','Desktop' => 'ડેસ્કટોપ','Preview width' => 'પૂર્વાવલોકન પહોળાઈ','Decrease width' => 'પહોળાઈ ઘટાડો','Preview width in pixels' => 'પિક્સેલ્સમાં પહોળાઈનું પૂર્વાવલોકન કરો','Increase width' => 'પહોળાઈ વધારો','Preview as' => 'આ રીતે પૂર્વાવલોકન કરો','Guest' => 'મહેમાન','Logged in' => 'લૉગ ઇન કર્યું','Preview page' => 'પૂર્વાવલોકન પૃષ્ઠ','Expand preview for a closer look' => 'નજીકથી જોવા માટે પૂર્વાવલોકન વિસ્તૃત કરો','Available with %s.' => '%s સાથે ઉપલબ્ધ.','Turn them on' => 'તેમને ચાલુ કરો','Optimizations for this page are turned off. %s to preview the page.' => 'આ પૃષ્ઠ માટે ઑપ્ટિમાઇઝેશન બંધ છે. પૃષ્ઠનું પૂર્વાવલોકન કરવા માટે %s.','%s preview' => '%s પૂર્વાવલોકન','Isolated session · nothing is saved' => 'અલગ સત્ર · કંઈ સાચવવામાં આવ્યું નથી','Usage tracking' => 'વપરાશ ટ્રેકિંગ','Send non-sensitive site environment reports to help Fluid Checkout improve compatibility. Reports are not sent until enabled in the options below.' => 'ફ્લુઇડ ચેકઆઉટને સુસંગતતા સુધારવામાં મદદ કરવા માટે બિન-સંવેદનશીલ સાઇટ પર્યાવરણ રિપોર્ટ્સ મોકલો. નીચેના વિકલ્પોમાં સક્ષમ ન થાય ત્યાં સુધી રિપોર્ટ્સ મોકલવામાં આવતા નથી.','Send usage tracking reports to Fluid Checkout' => 'ફ્લુઇડ ચેકઆઉટને વપરાશ ટ્રેકિંગ રિપોર્ટ્સ મોકલો','These reports help us improve compatibility and support for your site and are sent weekly when enabled.' => 'આ રિપોર્ટ્સ અમને તમારી સાઇટ માટે સુસંગતતા અને સપોર્ટ સુધારવામાં મદદ કરે છે અને જ્યારે સક્ષમ હોય ત્યારે દર અઠવાડિયે મોકલવામાં આવે છે.','No customer, admin user, or any other sensitive data is included in the reports.' => 'રિપોર્ટ્સમાં કોઈ ગ્રાહક, એડમિન વપરાશકર્તા અથવા અન્ય કોઈ સંવેદનશીલ ડેટાનો સમાવેશ થતો નથી.','Basic environment info' => 'મૂળભૂત પર્યાવરણ માહિતી','WordPress, PHP, WooCommerce, theme, and plugin list data. Always included when reporting is enabled. Helps us understand the environment your site is running in.' => 'વર્ડપ્રેસ, PHP, WooCommerce, થીમ અને પ્લગઇન સૂચિ ડેટા. રિપોર્ટિંગ સક્ષમ હોય ત્યારે હંમેશા શામેલ હોય છે. તમારી સાઇટ કયા વાતાવરણમાં ચાલી રહી છે તે સમજવામાં અમને મદદ કરે છે.','Plugin settings' => 'પ્લગઇન સેટિંગ્સ','Sends Fluid Checkout plugin settings to help with support requests and helps us understand how you are using our plugins.' => 'સપોર્ટ વિનંતીઓમાં મદદ કરવા માટે ફ્લુઇડ ચેકઆઉટ પ્લગઇન સેટિંગ્સ મોકલે છે અને તમે અમારા પ્લગઇન્સનો ઉપયોગ કેવી રીતે કરી રહ્યા છો તે સમજવામાં અમને મદદ કરે છે.','Coming soon' => 'ટૂંક સમયમાં આવી રહ્યું છે','Sales metrics' => 'વેચાણ મેટ્રિક્સ','Monthly order count and total sales for one year prior to installing Fluid Checkout up to today. Helps us understand if you are making more money with our plugins installed. No customer or user data is ever sent.' => 'ફ્લુઇડ ચેકઆઉટ ઇન્સ્ટોલ કર્યા પહેલાના એક વર્ષ માટે આજ સુધી માસિક ઓર્ડર ગણતરી અને કુલ વેચાણ. અમારા પ્લગઇન્સ ઇન્સ્ટોલ કરીને તમે વધુ પૈસા કમાઈ રહ્યા છો કે નહીં તે સમજવામાં અમને મદદ કરે છે. ક્યારેય કોઈ ગ્રાહક કે વપરાશકર્તા ડેટા મોકલવામાં આવતો નથી.','Utilities' => 'ઉપયોગિતાઓ','Use <code>TomSelect</code> dropdown components instead of <code>select2</code>' => '<code>select2</code> ને બદલે <code>TomSelect</code> ડ્રોપડાઉન ઘટકોનો ઉપયોગ કરો.','TomSelect is a simpler dropdown selection component which is less prone to errors than Select2, while offering the same functionality.' => 'ટોમસિલેક્ટ એ એક સરળ ડ્રોપડાઉન પસંદગી ઘટક છે જે Select2 કરતા ઓછી ભૂલો માટે સંવેદનશીલ છે, જ્યારે તે સમાન કાર્યક્ષમતા પ્રદાન કરે છે.','Sets the font size inside form fields to 16px on pages optimized by this plugin to avoid automatically zooming in when interacting with form fields on small devices.' => 'નાના ઉપકરણો પર ફોર્મ ફીલ્ડ્સ સાથે ક્રિયાપ્રતિક્રિયા કરતી વખતે આપમેળે ઝૂમ ઇન થવાનું ટાળવા માટે આ પ્લગઇન દ્વારા ઑપ્ટિમાઇઝ કરેલા પૃષ્ઠો પર ફોર્મ ફીલ્ડ્સની અંદર ફોન્ટ કદ 16px પર સેટ કરે છે.','Safari and other browsers might automatically zoom in on mobile devices to make the text easier to read when the font size is smaller than 16px.' => 'જ્યારે ફોન્ટનું કદ ૧૬ પિક્સેલ કરતા નાનું હોય ત્યારે ટેક્સ્ટ વાંચવામાં સરળતા રહે તે માટે સફારી અને અન્ય બ્રાઉઝર્સ મોબાઇલ ઉપકરણો પર આપમેળે ઝૂમ ઇન કરી શકે છે.','Enable script processing tracking on the browser console.' => 'બ્રાઉઝર કન્સોલ પર સ્ક્રિપ્ટ પ્રોસેસિંગ ટ્રેકિંગ સક્ષમ કરો.','Unminified assets' => 'અમર્યાદિત સંપત્તિઓ','Google Maps scripts' => 'ગૂગલ મેપ્સ સ્ક્રિપ્ટ્સ','Do not remove duplicate Google Maps scripts' => 'ડુપ્લિકેટ ગૂગલ મેપ્સ સ્ક્રિપ્ટ્સ દૂર કરશો નહીં','When enabled, duplicate Google Maps scripts will NOT be removed which can cause errors and performance issues. Only use this option while troubleshooting.' => 'જ્યારે સક્ષમ હોય, ત્યારે ડુપ્લિકેટ Google નકશા સ્ક્રિપ્ટો દૂર કરવામાં આવશે નહીં જેના કારણે ભૂલો અને પ્રદર્શન સમસ્યાઓ થઈ શકે છે. મુશ્કેલીનિવારણ કરતી વખતે જ આ વિકલ્પનો ઉપયોગ કરો.','Widget areas' => 'વિજેટ વિસ્તારો','Last step on mobile' => 'મોબાઇલ પર છેલ્લું પગલું','Display widgets only at last step on mobile' => 'મોબાઇલ પર ફક્ત છેલ્લા પગલા પર વિજેટ્સ દર્શાવો','Display checkout trust badge widgets only when viewing the last checkout step on mobile devices' => 'મોબાઇલ ઉપકરણો પર છેલ્લું ચેકઆઉટ પગલું જોતી વખતે જ ચેકઆઉટ ટ્રસ્ટ બેજ વિજેટ્સ પ્રદર્શિત કરો','Standard' => 'માનક','VAT number field' => 'VAT નંબર ફીલ્ડ','Add a VAT number field to the billing form.' => 'બિલિંગ ફોર્મમાં VAT નંબર ફીલ્ડ ઉમેરો.','Field label' => 'ફીલ્ડ લેબલ','Set the label of the VAT number field (ie. VAT number). On multi-language websites, it is better to leave this field empty and translate the original string.' => 'VAT નંબર ફીલ્ડ (એટલે કે VAT નંબર) નું લેબલ સેટ કરો. બહુભાષી વેબસાઇટ્સ પર, આ ફીલ્ડ ખાલી રાખવું અને મૂળ સ્ટ્રિંગનો અનુવાદ કરવો વધુ સારું છે.','VAT Number' => 'વેટ નંબર','EU-VAT' => 'EU-વેટ','Enable the VAT number field to see more options' => 'વધુ વિકલ્પો જોવા માટે VAT નંબર ફીલ્ડ સક્ષમ કરો.','VAT validation' => 'VAT માન્યતા','Validate VAT number field for EU-VAT during checkout' => 'ચેકઆઉટ દરમિયાન EU-VAT માટે VAT નંબર ફીલ્ડ માન્ય કરો','Checks if the VAT Number provided is a valid VAT number registered on the European VIES Database (VAT Information Exchange System).' => 'આપેલ VAT નંબર યુરોપિયન VIES ડેટાબેઝ (VAT ઇન્ફર્મેશન એક્સચેન્જ સિસ્ટમ) પર નોંધાયેલ માન્ય VAT નંબર છે કે કેમ તે તપાસે છે.','Shop VAT number' => 'દુકાનનો VAT નંબર','The shop\'s VAT number used for requesting EU-VAT validation, and printed on invoices. <br><strong>We strongly recommend adding your Shop VAT number</strong> as otherwise the VIES consultation results might not be valid for accounting purposes. <br>Ie.: <code>ATU99999999</code> or <code>EE999999999</code>.' => 'EU-VAT માન્યતાની વિનંતી કરવા માટે વપરાયેલ દુકાનનો VAT નંબર, અને ઇન્વોઇસ પર છાપેલ.<br> <strong>અમે તમારો શોપ VAT નંબર ઉમેરવાની ભારપૂર્વક ભલામણ કરીએ છીએ</strong> કારણ કે અન્યથા VIES કન્સલ્ટેશન પરિણામો એકાઉન્ટિંગ હેતુઓ માટે માન્ય ન પણ હોય.<br> એટલે કે.: <code>ATU99999999</code> અથવા <code>EE999999999</code> .','Reverse charge' => 'રિવર્સ ચાર્જ','Apply reverse charge mechanism' => 'રિવર્સ ચાર્જ મિકેનિઝમ લાગુ કરો','Set tax rate to zero and display "Reverse charge" on invoices when the customer\'s VAT number is valid. A different "Reverse charge" text might be required depending on the store\'s country.' => 'જ્યારે ગ્રાહકનો VAT નંબર માન્ય હોય ત્યારે કર દર શૂન્ય પર સેટ કરો અને ઇન્વોઇસ પર &quot;રિવર્સ ચાર્જ&quot; દર્શાવો. સ્ટોરના દેશના આધારે અલગ &quot;રિવર્સ ચાર્જ&quot; ટેક્સ્ટની જરૂર પડી શકે છે.','Same country' => 'એ જ દેશ','Apply reverse charge mechanism for transactions in the shop country:' => 'દુકાનના દેશમાં વ્યવહારો માટે રિવર્સ ચાર્જ મિકેનિઝમ લાગુ કરો:','Enables applying reverse charge mechanism for transactions between companies in the same country as the shop.' => 'દુકાન જે દેશમાં છે તે જ દેશમાં કંપનીઓ વચ્ચેના વ્યવહારો માટે રિવર્સ ચાર્જ મિકેનિઝમ લાગુ કરવાનું સક્ષમ કરે છે.','Reverse charge exceptions' => 'રિવર્સ ચાર્જ અપવાદો','Select additional countries to skip applying the reverse charge mechanism.' => 'રિવર્સ ચાર્જ મિકેનિઝમ લાગુ કરવાનું છોડી દેવા માટે વધારાના દેશો પસંદ કરો.','Taxes will be charged to orders from these countries even when a valid VAT number is provided.' => 'માન્ય VAT નંબર આપવામાં આવ્યો હોય તો પણ આ દેશોના ઓર્ડર પર કર વસૂલવામાં આવશે.','Reverse charge label on invoices' => 'ઇન્વોઇસ પર રિવર્સ ચાર્જ લેબલ','Set the label of "reverse charge" on the checkout page and order details.' => 'ચેકઆઉટ પેજ અને ઓર્ડર વિગતો પર &quot;રિવર્સ ચાર્જ&quot; નું લેબલ સેટ કરો.','Reverse charge text on invoices' => 'ઇન્વોઇસ પર રિવર્સ ચાર્જ ટેક્સ્ટ','Set the label of "reverse charge" text on invoices.' => 'ઇન્વોઇસ પર &quot;રિવર્સ ચાર્જ&quot; ટેક્સ્ટનું લેબલ સેટ કરો.','Tax to be paid on reverse charge basis' => 'રિવર્સ ચાર્જ આધારે ચૂકવવાનો કર','Company name' => 'કંપનીનું નામ','Autocomplete company name from VAT number' => 'VAT નંબર પરથી કંપનીનું નામ સ્વતઃપૂર્ણ કરો','Fill in the billing company name based on the valid VAT number provided by the customer.' => 'ગ્રાહક દ્વારા પૂરા પાડવામાં આવેલ માન્ય VAT નંબરના આધારે બિલિંગ કંપનીનું નામ ભરો.','Company name editing' => 'કંપનીના નામમાં ફેરફાર','Allow editing of auto-filled company name' => 'આપમેળે ભરેલા કંપનીના નામના સંપાદનને મંજૂરી આપો','When enabled, customers can change the company name associated with the provided VAT number.' => 'જ્યારે સક્ષમ હોય, ત્યારે ગ્રાહકો આપેલા VAT નંબર સાથે સંકળાયેલ કંપનીનું નામ બદલી શકે છે.','EU-VAT for digital goods' => 'ડિજિટલ માલ માટે EU-VAT','From January 1st, 2015, modifications have been made to the EU VAT regulations concerning digital goods, impacting exclusively B2C transactions. The VAT on digital goods must be calculated based on the customer\'s location, and evidence of this needs to be collected (IP address and billing address).' => '૧ જાન્યુઆરી, ૨૦૧૫ થી, ડિજિટલ માલ સંબંધિત EU VAT નિયમોમાં ફેરફારો કરવામાં આવ્યા છે, જે ફક્ત B2C વ્યવહારોને અસર કરે છે. ડિજિટલ માલ પરના VAT ની ગણતરી ગ્રાહકના સ્થાનના આધારે થવી જોઈએ, અને આના પુરાવા (IP સરનામું અને બિલિંગ સરનામું) એકત્રિત કરવાની જરૂર છે.','Tax classes for digital goods' => 'ડિજિટલ માલ માટે કર વર્ગો','Select some tax classes' => 'કેટલાક ટેક્સ વર્ગો પસંદ કરો','Location evidence' => 'સ્થાન પુરાવા','Collect customer\'s location evidence' => 'ગ્રાહકના સ્થાનના પુરાવા એકત્રિત કરો','Saves the IP address and validate it against the customer\'s billing address. Customer\'s must confirm their billing address by checking a checkbox on the checkout page if the country from their billing address and IP do not match.' => 'IP સરનામું સાચવે છે અને ગ્રાહકના બિલિંગ સરનામાં સામે તેને માન્ય કરે છે. જો ગ્રાહકના બિલિંગ સરનામાં અને IP માંથી દેશ મેળ ખાતો નથી, તો તેમણે ચેકઆઉટ પૃષ્ઠ પર ચેકબોક્સ ચેક કરીને તેમના બિલિંગ સરનામાંની પુષ્ટિ કરવી આવશ્યક છે.','This option is managed in Fluid Checkout. <a href="%s">Change it in Customer accounts settings</a>.' => 'આ વિકલ્પ ફ્લુઇડ ચેકઆઉટમાં મેનેજ થાય છે. <a href="%s">તેને ગ્રાહક એકાઉન્ટ સેટિંગ્સમાં બદલો</a> .','This option is managed in Fluid Checkout. Change it under Fluid Checkout > Customer accounts.' => 'આ વિકલ્પ ફ્લુઇડ ચેકઆઉટમાં મેનેજ થાય છે. તેને ફ્લુઇડ ચેકઆઉટ &gt; ગ્રાહક એકાઉન્ટ્સ હેઠળ બદલો.','This option is managed in Fluid Checkout. The shipping destination is always set to "Default to customer shipping address" when Fluid Checkout is activated. Customers can still provide different shipping and billing addresses during checkout.<br><br>An option for setting the default billing address to be the same as the shipping address is available in the <a href="%s">Fluid Checkout settings</a>.' => 'આ વિકલ્પ ફ્લુઇડ ચેકઆઉટમાં મેનેજ થાય છે. જ્યારે ફ્લુઇડ ચેકઆઉટ સક્રિય થાય છે ત્યારે શિપિંગ ગંતવ્ય હંમેશા &quot;ગ્રાહક શિપિંગ સરનામાં પર ડિફોલ્ટ&quot; પર સેટ હોય છે. ગ્રાહકો ચેકઆઉટ દરમિયાન હજુ પણ અલગ અલગ શિપિંગ અને બિલિંગ સરનામાં પ્રદાન કરી શકે છે.<br><br> <a href="%s">ફ્લુઇડ ચેકઆઉટ સેટિંગ્સમાં</a> ડિફોલ્ટ બિલિંગ સરનામાંને શિપિંગ સરનામાં જેવો જ સેટ કરવાનો વિકલ્પ ઉપલબ્ધ છે.','This option is managed in Fluid Checkout. The shipping destination is always set to "Default to customer shipping address" when Fluid Checkout is activated. Customers can still provide different shipping and billing addresses during checkout.<br><br>An option for setting the default billing address to be the same as the shipping address is available at WooCommerce > Settings > Fluid Checkout.' => 'આ વિકલ્પ ફ્લુઇડ ચેકઆઉટમાં મેનેજ થાય છે. જ્યારે ફ્લુઇડ ચેકઆઉટ સક્રિય થાય છે ત્યારે શિપિંગ ગંતવ્ય હંમેશા &quot;ગ્રાહક શિપિંગ સરનામાં પર ડિફોલ્ટ&quot; પર સેટ હોય છે. ગ્રાહકો ચેકઆઉટ દરમિયાન હજુ પણ અલગ અલગ શિપિંગ અને બિલિંગ સરનામાં પ્રદાન કરી શકે છે.<br><br> ડિફોલ્ટ બિલિંગ સરનામું શિપિંગ સરનામાં જેવું જ સેટ કરવાનો વિકલ્પ WooCommerce &gt; Settings &gt; Fluid Checkout પર ઉપલબ્ધ છે.','These settings have been moved to WP Admin > Fluid Checkout > Settings.' => 'આ સેટિંગ્સ WP એડમિન &gt; ફ્લુઇડ ચેકઆઉટ &gt; સેટિંગ્સમાં ખસેડવામાં આવી છે.','This WooCommerce Settings tab is deprecated and will be removed in Fluid Checkout 6.0.' => 'આ WooCommerce સેટિંગ્સ ટેબ દૂર કરવામાં આવ્યું છે અને તેને Fluid Checkout 6.0 માં દૂર કરવામાં આવશે.','Go to settings page' => 'સેટિંગ્સ પેજ પર જાઓ','Hide this tab permanently' => 'આ ટેબ કાયમ માટે છુપાવો','Site report preview' => 'સાઇટ રિપોર્ટ પૂર્વાવલોકન','This is the data that would be included in the next site environment report based on your current settings.' => 'આ તે ડેટા છે જે તમારી વર્તમાન સેટિંગ્સના આધારે આગામી સાઇટ પર્યાવરણ રિપોર્ટમાં શામેલ કરવામાં આવશે.','Loading report preview...' => 'રિપોર્ટ પૂર્વાવલોકન લોડ કરી રહ્યું છે...','Could not load the site report preview. Try again.' => 'સાઇટ રિપોર્ટ પ્રીવ્યૂ લોડ કરી શકાયો નથી. ફરી પ્રયાસ કરો.','Could not send the site report. Try again.' => 'સાઇટ રિપોર્ટ મોકલી શકાયો નથી. ફરી પ્રયાસ કરો.','Site report sent successfully.' => 'સાઇટ રિપોર્ટ સફળતાપૂર્વક મોકલવામાં આવ્યો.','Enable and send now' => 'સક્ષમ કરો અને હમણાં મોકલો','Close' => 'બંધ કરો','A site report request is already in progress. Try again in a moment.' => 'સાઇટ રિપોર્ટ વિનંતી પહેલાથી જ પ્રક્રિયામાં છે. થોડીવારમાં ફરી પ્રયાસ કરો.','Site environment reporting is disabled.' => 'સાઇટ પર્યાવરણ રિપોર્ટિંગ અક્ષમ છે.','No site report data is available to send.' => 'મોકલવા માટે કોઈ સાઇટ રિપોર્ટ ડેટા ઉપલબ્ધ નથી.','This site domain cannot send environment reports (local or development domains are excluded).' => 'આ સાઇટ ડોમેન પર્યાવરણ અહેવાલો મોકલી શકતું નથી (સ્થાનિક અથવા વિકાસ ડોમેન બાકાત રાખવામાં આવ્યા છે).','A site report was sent recently. Try again later.' => 'તાજેતરમાં એક સાઇટ રિપોર્ટ મોકલવામાં આવ્યો હતો. પછીથી ફરી પ્રયાસ કરો.','The site report could not be sent. Try again later.' => 'સાઇટ રિપોર્ટ મોકલી શકાયો નથી. પછીથી ફરી પ્રયાસ કરો.','Site environment reporting is not available.' => 'સાઇટ પર્યાવરણ રિપોર્ટિંગ ઉપલબ્ધ નથી.','No site report data is available for the selected settings.' => 'પસંદ કરેલી સેટિંગ્સ માટે કોઈ સાઇટ રિપોર્ટ ડેટા ઉપલબ્ધ નથી.','You are not allowed to manage site reports.' => 'તમને સાઇટ રિપોર્ટ્સ મેનેજ કરવાની મંજૂરી નથી.','PRO feature' => 'પ્રો સુવિધા','Other plugins' => 'અન્ય પ્લગઇન્સ','Get only this add-on &mdash; %s' => 'ફક્ત આ એડ-ઓન મેળવો — %s','Install add-on' => 'એડ-ઓન ઇન્સ્ટોલ કરો','Upgrade to PRO &mdash; %s' => 'PRO — %s માં અપગ્રેડ કરો','<a target="_blank" href="%1$s">Get %2$s</a> to unlock these options.' => 'આ વિકલ્પોને અનલૉક કરવા માટે <a target="_blank" href="%1$s">%2$s મેળવો</a> .','Add-on' => 'એડ-ઓન','View documentation' => 'દસ્તાવેજીકરણ જુઓ','Requests require a logged-in WordPress user. Omit user_id to use the current user\'s data, or pass user_id to target another account when the caller can edit that user (edit_user capability). Unauthenticated requests return fc_api_forbidden. An invalid user_id returns fc_api_user_not_found.' => 'વિનંતીઓ માટે લૉગ-ઇન WordPress વપરાશકર્તાની જરૂર પડે છે. વર્તમાન વપરાશકર્તાના ડેટાનો ઉપયોગ કરવા માટે user_id છોડી દો, અથવા જ્યારે કૉલર તે વપરાશકર્તાને સંપાદિત કરી શકે ત્યારે બીજા એકાઉન્ટને લક્ષ્ય બનાવવા માટે user_id પાસ કરો (edit_user ક્ષમતા). અમાન્ય વિનંતીઓ fc_api_forbidden પરત કરે છે. અમાન્ય user_id fc_api_user_not_found પરત કરે છે.','HTTP 200 with { "data": { ... } } when the handler returns a payload.' => 'જ્યારે હેન્ડલર પેલોડ પરત કરે છે ત્યારે HTTP 200 { &quot;data&quot;: { ... } } સાથે.','HTTP 200 with { "success": true } when there is no payload (for example DELETE).' => 'જ્યારે કોઈ પેલોડ ન હોય ત્યારે HTTP 200 { &quot;સફળતા&quot;: સાચું } સાથે (ઉદાહરણ તરીકે DELETE).','Failures return WordPress REST error JSON from WP_Error (code, message, data.status). Wire codes use the fc_api_* prefix.' => 'નિષ્ફળતાઓ WP_Error (કોડ, સંદેશ, data.status) માંથી WordPress REST ભૂલ JSON પરત કરે છે. વાયર કોડ્સ fc_api_* ઉપસર્ગનો ઉપયોગ કરે છે.','Forbidden access.' => 'પ્રતિબંધિત પ્રવેશ.','Target user was not found.' => 'લક્ષ્ય વપરાશકર્તા મળ્યો ન હતો.','This feature is not available.' => 'આ સુવિધા ઉપલબ્ધ નથી.','A required address field is missing.' => 'જરૂરી સરનામાં ફીલ્ડ ખૂટે છે.','Postcode or ZIP is invalid.' => 'પોસ્ટકોડ અથવા ઝીપ અમાન્ય છે.','Phone number is invalid.' => 'ફોન નંબર અમાન્ય છે.','State or county is invalid.' => 'રાજ્ય અથવા કાઉન્ટી અમાન્ય છે.','Country is invalid or has no address fields.' => 'દેશ અમાન્ય છે અથવા તેમાં કોઈ સરનામાં ફીલ્ડ નથી.','The request could not be processed.' => 'વિનંતી પર પ્રક્રિયા કરી શકાઈ નથી.','Back to previous step' => 'પાછલા પગલાં પર પાછા જાઓ','Skip to settings' => 'સેટિંગ્સ પર જાઓ','Start over and return to the first guided setup step' => 'ફરીથી શરૂ કરો અને પહેલા માર્ગદર્શિત સેટઅપ પગલા પર પાછા ફરો','Start over' => 'ફરી શરૂ કરો','Please complete all sub-steps before continuing.' => 'આગળ વધતા પહેલા કૃપા કરીને બધા પેટા-પગલાં પૂર્ણ કરો.','Expand' => 'વિસ્તૃત કરો','Collapse' => 'સંકુચિત કરો','Skip' => 'છોડી દો','Mark as complete' => 'પૂર્ણ તરીકે ચિહ્નિત કરો','Mark as incomplete' => 'અપૂર્ણ તરીકે ચિહ્નિત કરો','View full-size image: %s' => 'પૂર્ણ-કદની છબી જુઓ: %s','Full-size setup guide image' => 'પૂર્ણ-કદની સેટઅપ માર્ગદર્શિકા છબી','Close image' => 'છબી બંધ કરો','Fluid Checkout Guided Setup' => 'ફ્લુઇડ ચેકઆઉટ માર્ગદર્શિત સેટઅપ','Welcome' => 'સ્વાગત છે','Explore your checkout' => 'તમારા ચેકઆઉટનું અન્વેષણ કરો','All set' => 'બધું સેટ છે','You do not have permission to access this page.' => 'તમને આ પૃષ્ઠને ઍક્સેસ કરવાની પરવાનગી નથી.','Go to step %1$d: %2$s' => 'પગલાં %1$d પર જાઓ: %2$s','This guided setup helps you get familiar with Fluid Checkout. The steps below are placeholders for now.' => 'આ માર્ગદર્શિત સેટઅપ તમને ફ્લુઇડ ચેકઆઉટથી પરિચિત થવામાં મદદ કરે છે. નીચે આપેલા પગલાં હાલ માટે પ્લેસહોલ્ડર છે.','Continue to the next step when you are ready.' => 'જ્યારે તમે તૈયાર હોવ ત્યારે આગલા પગલા પર આગળ વધો.','Open your store checkout to see Fluid Checkout in action.' => 'ફ્લુઇડ ચેકઆઉટ કાર્યમાં જોવા માટે તમારા સ્ટોર ચેકઆઉટ ખોલો.','View checkout page' => 'ચેકઆઉટ પેજ જુઓ','You can return to Fluid Checkout settings to continue configuring your store.' => 'તમારા સ્ટોરને ગોઠવવાનું ચાલુ રાખવા માટે તમે ફ્લુઇડ ચેકઆઉટ સેટિંગ્સ પર પાછા આવી શકો છો.','Review checkout and cart settings' => 'ચેકઆઉટ અને કાર્ટ સેટિંગ્સની સમીક્ષા કરો','Explore add-ons from the dashboard' => 'ડેશબોર્ડ પરથી એડ-ઓન્સનું અન્વેષણ કરો','Finish & go to settings' => 'પૂર્ણ કરો અને સેટિંગ્સ પર જાઓ','Update the billing phone field visibility option from the legacy value to match WooCommerce conventions.' => 'WooCommerce કન્વેન્શન સાથે મેળ ખાતી લેગસી મૂલ્યમાંથી બિલિંગ ફોન ફીલ્ડ દૃશ્યતા વિકલ્પને અપડેટ કરો.','Update the shipping phone field visibility option from the legacy value to match WooCommerce conventions.' => 'WooCommerce કન્વેન્શન સાથે મેળ ખાતી લેગસી મૂલ્યમાંથી શિપિંગ ફોન ફીલ્ડ દૃશ્યતા વિકલ્પને અપડેટ કરો.','Copy the order summary background color setting to the new Split design secondary column background color option.' => 'ઓર્ડર સારાંશ પૃષ્ઠભૂમિ રંગ સેટિંગને નવા સ્પ્લિટ ડિઝાઇન ગૌણ કૉલમ પૃષ્ઠભૂમિ રંગ વિકલ્પમાં કૉપિ કરો.','The enhanced select fields feature is always disabled when using the Biteship plugin.' => 'બાઈટશીપ પ્લગઈનનો ઉપયોગ કરતી વખતે ઉન્નત પસંદગી ક્ષેત્રોની સુવિધા હંમેશા અક્ષમ રહે છે.','The place order position is always set to "Below the order summary" when using German Market. That plugin requires the place order button and legal checkboxes to be displayed below the order summary.' => 'જર્મન માર્કેટનો ઉપયોગ કરતી વખતે પ્લેસ ઓર્ડર પોઝિશન હંમેશા &quot;ઓર્ડર સારાંશની નીચે&quot; પર સેટ કરેલી હોય છે. તે પ્લગઇન માટે ઓર્ડર સારાંશની નીચે પ્લેસ ઓર્ડર બટન અને કાનૂની ચેકબોક્સ પ્રદર્શિત કરવા જરૂરી છે.','The place order position is always set to "Below the order summary" when using Germanized for WooCommerce. That plugin requires the place order button and legal checkboxes to be displayed below the order summary.' => 'WooCommerce માટે જર્મનાઇઝ્ડનો ઉપયોગ કરતી વખતે પ્લેસ ઓર્ડર પોઝિશન હંમેશા &quot;ઓર્ડર સારાંશની નીચે&quot; પર સેટ કરેલી હોય છે. તે પ્લગઇન માટે ઓર્ડર સારાંશની નીચે પ્લેસ ઓર્ડર બટન અને કાનૂની ચેકબોક્સ પ્રદર્શિત કરવા જરૂરી છે.','Edit pickup locations' => 'પિકઅપ સ્થાનોમાં ફેરફાર કરો','Use local pickup label from WooCommerce settings' => 'WooCommerce સેટિંગ્સમાંથી સ્થાનિક પિકઅપ લેબલનો ઉપયોગ કરો','When enabled, the pickup option label on checkout matches the title from WooCommerce pickup location settings. When disabled, the label uses the translatable "Local pickup" text from Fluid Checkout.' => 'જ્યારે સક્ષમ હોય, ત્યારે ચેકઆઉટ પર પિકઅપ વિકલ્પ લેબલ WooCommerce પિકઅપ સ્થાન સેટિંગ્સમાંથી શીર્ષક સાથે મેળ ખાય છે. જ્યારે અક્ષમ હોય, ત્યારે લેબલ ફ્લુઇડ ચેકઆઉટમાંથી અનુવાદ કરી શકાય તેવા &quot;સ્થાનિક પિકઅપ&quot; ટેક્સ્ટનો ઉપયોગ કરે છે.','Button label for applying coupon codesApply' => 'અરજી કરો','Checkout step titleContact' => 'સંપર્ક કરો','Checkout step titleShipping' => 'શિપિંગ','Checkout step titleBilling' => 'બિલિંગ','Checkout step titlePayment' => 'ચુકવણી','Checkout substep change link labelChange' => 'બદલો','Checkout substep save link labelSave changes' => 'ફેરફારો સાચવો','Substep review textNone.' => 'કોઈ નહીં.','Substep review field format%1$s' => '%1$s','Substep review field format: with label%2$s: %1$s' => '%2$s: %1$s','Image uploader.No image selected.' => 'કોઈ છબી પસંદ કરેલી નથી.','Settings sectionCart' => 'કાર્ટ','Settings sectionOrder pay' => 'ઓર્ડર પગાર','Settings sectionThank you' => 'આભાર','Settings section titleIntegrations' => 'એકીકરણ','Settings section titleLicense keys' => 'લાઇસન્સ કીઓ','Captcha positionBefore place order section' => 'ઓર્ડર આપતા પહેલાનો વિભાગ','Captcha positionBefore place order button' => 'ઓર્ડર આપતા પહેલા બટન','No shipping method chosen label for the order summary--' => '--','Close button a